input.content:
:root {
  --ink: #08050f;
  --ink-2: #0e0919;
  --violet: #a97cff;
  --violet-deep: #6d43c9;
  --ember: #ff9a4d;
  --ember-hot: #ffd29a;
  --bone: #f2e8d8;
  --muted: #a89bbd;
  --moss: #7fd8a6;
  --frost: #8fe1ff;
  --danger: #ff5d73;
  --line: rgba(190, 160, 255, .18);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }

html, body {
  width: 100%; height: 100%; overflow: hidden;
  background: var(--ink);
  color: var(--bone);
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none; -webkit-user-select: none;
}

#app { position: fixed; inset: 0; overflow: hidden; background: #08060f; }

#game {
  position: absolute; inset: 0; width: 100%; height: 100%;
  display: block; touch-action: none; cursor: crosshair;
}

.hidden { display: none !important; }

button { font-family: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
svg { display: block; }

/* ───────────────────────── HUD ───────────────────────── */
#hud {
  position: absolute; inset: 0; pointer-events: none;
  padding: calc(10px + var(--safe-t)) calc(12px + var(--safe-r)) calc(10px + var(--safe-b)) calc(12px + var(--safe-l));
  display: flex; flex-direction: column;
}

.hud-top { display: flex; align-items: flex-start; gap: 10px; justify-content: space-between; }

.witch-plate {
  display: flex; align-items: center; gap: 8px;
  filter: drop-shadow(0 3px 8px rgba(0,0,0,.65));
}
.portrait {
  position: relative; width: 44px; height: 44px; flex: 0 0 44px;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, #3c2466 0%, #191026 70%);
  border: 1.5px solid rgba(190,150,255,.55);
  box-shadow: inset 0 0 12px rgba(150,110,255,.35), 0 0 14px rgba(120,70,220,.25);
  display: grid; place-items: center;
}
.portrait svg { width: 34px; height: 34px; }
.portrait .lvl {
  position: absolute; right: -5px; bottom: -4px;
  min-width: 20px; height: 20px; padding: 0 4px;
  display: grid; place-items: center;
  border-radius: 10px;
  font-size: 11px; font-weight: 800; letter-spacing: .3px;
  color: #1a0f2c;
  background: linear-gradient(160deg, #ffe3ae, #e0a45c);
  border: 1px solid #fff0cf;
  box-shadow: 0 2px 6px rgba(0,0,0,.5);
}

.bars { display: flex; flex-direction: column; gap: 4px; width: clamp(104px, 24vw, 172px); }
.bar {
  position: relative; height: 11px; border-radius: 7px; overflow: hidden;
  background: rgba(7,4,14,.72);
  border: 1px solid rgba(190,160,255,.22);
  box-shadow: inset 0 1px 4px rgba(0,0,0,.6);
}
.bar i { position: absolute; inset: 0; width: 100%; transform-origin: left; transition: width .18s ease-out; }
.bar.hp { height: 13px; }
.bar.hp i { background: linear-gradient(90deg, #932a4a, #f0637e 55%, #ff9a90); box-shadow: 0 0 12px rgba(255,90,120,.35); }
.bar.xp { height: 7px; }
.bar.xp i { background: linear-gradient(90deg, #5c3bd6, #b07cff 70%, #e3c8ff); box-shadow: 0 0 10px rgba(170,120,255,.5); }
.bar b {
  position: absolute; inset: 0; display: grid; place-items: center;
  font-size: 9px; font-weight: 700; letter-spacing: .4px; color: rgba(255,240,240,.92);
  text-shadow: 0 1px 2px rgba(0,0,0,.9);
}

.run-clock { text-align: center; flex: 1; padding-top: 1px; filter: drop-shadow(0 2px 6px rgba(0,0,0,.75)); }
.clock-label { font-size: 8px; letter-spacing: 2.6px; color: rgba(215,195,255,.62); font-weight: 700; }
.clock-time {
  font-family: Georgia, "Times New Roman", serif;
  font-variant-numeric: tabular-nums;
  font-size: clamp(20px, 5.4vw, 28px);
  line-height: 1.05; letter-spacing: .5px;
  color: #f7ecd9;
  text-shadow: 0 0 16px rgba(255,190,120,.22);
}
.clock-goal {
  font-size: 8.5px; letter-spacing: .9px; color: #cbb9e6; opacity: .82;
  max-width: 150px; margin: 1px auto 0; line-height: 1.3;
  text-transform: uppercase;
}

.kill-plate { display: flex; align-items: center; gap: 6px; filter: drop-shadow(0 2px 6px rgba(0,0,0,.7)); }
.kills { font-family: Georgia, serif; font-size: 22px; line-height: 1; color: #ffe6bd; font-variant-numeric: tabular-nums; }
.kill-label { font-size: 7.5px; letter-spacing: 1.5px; color: rgba(215,195,255,.6); font-weight: 700; margin-right: 2px; }

.icon-btn {
  width: 32px; height: 32px; display: grid; place-items: center;
  border-radius: 50%;
  color: #cbb9e6;
  background: rgba(15,10,27,.6);
  border: 1px solid rgba(190,160,255,.2);
  pointer-events: auto;
  transition: background .15s, color .15s;
}
.icon-btn svg { width: 17px; height: 17px; }
.icon-btn:active { background: rgba(90,60,150,.4); }
.icon-btn.muted .wave { opacity: .12; }
.icon-btn.muted { color: #6f6385; }

/* boss bar */
#bossWrap {
  align-self: center; width: min(78%, 500px); margin-top: 10px;
  filter: drop-shadow(0 4px 10px rgba(0,0,0,.7));
  animation: bossIn .5s ease-out both;
}
@keyframes bossIn { from { opacity: 0; transform: translateY(-6px); } }
.boss-name {
  display: flex; justify-content: space-between; align-items: baseline;
  font-size: 9px; letter-spacing: 2px; font-weight: 800; color: #ffb2a8;
  padding: 0 2px 3px;
}
.boss-name em { font-style: normal; letter-spacing: .4px; font-size: 8.5px; color: rgba(255,220,210,.6); }
.boss-bar {
  height: 9px; border-radius: 6px; overflow: hidden;
  background: rgba(10,3,8,.8);
  border: 1px solid rgba(255,120,120,.34);
  box-shadow: inset 0 1px 4px rgba(0,0,0,.7);
}
.boss-bar i {
  display: block; height: 100%; width: 100%;
  background: linear-gradient(90deg, #6a1026, #c8364d 50%, #ff7a6a);
  box-shadow: 0 0 14px rgba(255,80,90,.55);
  transition: width .2s;
}

/* spell rail */
.spell-rail {
  position: absolute; left: calc(12px + var(--safe-l));
  top: calc(66px + var(--safe-t));
  display: flex; flex-direction: column; gap: 6px;
  pointer-events: none;
}
.spell-chip {
  position: relative; width: 34px; height: 34px; border-radius: 9px;
  background: rgba(13,8,24,.72);
  border: 1px solid rgba(170,130,255,.28);
  box-shadow: inset 0 0 10px rgba(100,60,180,.22), 0 2px 6px rgba(0,0,0,.4);
  display: grid; place-items: center;
  overflow: hidden;
  animation: chipIn .4s ease-out both;
}
@keyframes chipIn { from { opacity: 0; transform: translateX(-8px) scale(.8); } }
.spell-chip svg { width: 21px; height: 21px; color: var(--c, #c9aaff); }
.spell-chip .cd {
  position: absolute; inset: 0;
  background: rgba(4,2,9,.72);
  transform-origin: bottom;
  pointer-events: none;
}
.spell-chip .rk {
  position: absolute; right: 2px; bottom: 1px;
  font-size: 7px; font-weight: 800; color: #ffdfae;
  text-shadow: 0 1px 2px #000;
}
.spell-chip.new { animation: chipIn .4s ease-out both, chipPulse 1s ease-in-out 3; }
@keyframes chipPulse { 50% { box-shadow: 0 0 16px 2px rgba(200,150,255,.7); border-color: #fff; } }

.dash-btn {
  position: absolute; left: 50%; bottom: calc(22px + var(--safe-b));
  transform: translateX(-50%);
  width: 58px; height: 58px; border-radius: 50%;
  display: grid; place-items: center;
  pointer-events: auto;
  color: #ffe1b0;
  background: radial-gradient(circle at 50% 38%, rgba(88,58,150,.85), rgba(20,12,38,.92));
  border: 1.5px solid rgba(200,160,255,.45);
  box-shadow: 0 0 18px rgba(130,80,230,.3), inset 0 0 16px rgba(160,110,255,.22);
  touch-action: none;
}
.dash-btn svg { width: 26px; height: 26px; filter: drop-shadow(0 0 6px rgba(255,180,100,.5)); }
.dash-btn:active { transform: translateX(-50%) scale(.94); }
.dash-btn.cooling { color: #6c5c8a; border-color: rgba(140,110,190,.22); }
.dash-cd {
  position: absolute; inset: -1px; border-radius: 50%;
  background: conic-gradient(rgba(4,2,9,.78) var(--p, 0%), rgba(4,2,9,0) 0);
  pointer-events: none;
}

.wave-banner {
  position: absolute; left: 50%; top: 27%; transform: translate(-50%, -50%);
  font-family: Georgia, serif; font-size: clamp(18px, 4.4vw, 28px);
  color: #ffe9c9; letter-spacing: 3px; text-transform: uppercase;
  text-shadow: 0 0 24px rgba(255,150,80,.5), 0 3px 10px #000;
  opacity: 0; text-align: center; pointer-events: none; white-space: nowrap;
}
.wave-banner.show { animation: banner 2.6s ease-out both; }
@keyframes banner {
  0% { opacity: 0; transform: translate(-50%, -40%) scale(.92); letter-spacing: 8px; }
  14% { opacity: 1; transform: translate(-50%, -50%) scale(1); letter-spacing: 3px; }
  75% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -58%); }
}

.hint-line {
  position: absolute; left: 50%; bottom: calc(92px + var(--safe-b));
  transform: translateX(-50%);
  font-size: 9.5px; letter-spacing: .5px; color: rgba(220,200,250,.55);
  white-space: nowrap; opacity: 0; transition: opacity .8s; pointer-events: none;
  text-shadow: 0 1px 4px #000;
}
.hint-line.show { opacity: 1; }

/* ───────────────────────── overlays ───────────────────────── */
.overlay {
  position: absolute; inset: 0; z-index: 10;
  display: flex; align-items: center; justify-content: center;
  padding: calc(18px + var(--safe-t)) calc(16px + var(--safe-r)) calc(18px + var(--safe-b)) calc(16px + var(--safe-l));
  background: rgba(5, 3, 12, .74);
  -webkit-backdrop-filter: blur(7px);
  backdrop-filter: blur(7px);
  overflow-y: auto;
  animation: fadeIn .3s ease-out both;
}
@keyframes fadeIn { from { opacity: 0; } }

/* title */
.title-screen {
  background: radial-gradient(120% 85% at 50% 8%, #2a1745 0%, #130c22 45%, #07040d 100%);
  overflow: hidden;
  animation: fadeIn .6s ease-out both;
}
.title-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(70% 42% at 50% 108%, rgba(255,138,60,.14), transparent 68%),
    radial-gradient(52% 34% at 22% 8%, rgba(126,78,220,.22), transparent 70%),
    radial-gradient(44% 28% at 82% 22%, rgba(80,190,180,.09), transparent 70%);
  pointer-events: none;
}
.title-bg::after {
  content: ""; position: absolute; inset: 0;
  background-image: radial-gradient(rgba(255,255,255,.55) .6px, transparent .8px);
  background-size: 46px 46px; opacity: .13;
  mask-image: radial-gradient(70% 60% at 50% 35%, #000 0%, transparent 100%);
}
.title-screen::before {
  content: ""; position: absolute; left: 50%; bottom: -55vw;
  width: 140vw; height: 90vw; max-width: 1100px; max-height: 780px;
  transform: translateX(-50%);
  background: radial-gradient(ellipse at 50% 50%, rgba(110,60,190,.20), transparent 62%);
  border-radius: 50%;
  pointer-events: none;
}
.embers { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.embers i {
  position: absolute; left: var(--x); bottom: -12px;
  width: 5px; height: 5px; border-radius: 50%;
  background: radial-gradient(circle, #ffd9a0, #ff8a3d 45%, transparent 72%);
  filter: blur(.3px);
  opacity: 0;
  animation: rise var(--d) linear infinite;
  animation-delay: var(--dl);
  transform: scale(var(--s));
  box-shadow: 0 0 10px rgba(255,150,70,.7);
}
@keyframes rise {
  0% { opacity: 0; transform: translate(0, 0) scale(var(--s)); }
  12% { opacity: .9; }
  70% { opacity: .5; }
  100% { opacity: 0; transform: translate(34px, -104vh) scale(calc(var(--s) * .3)); }
}

.title-content { position: relative; z-index: 2; text-align: center; max-width: 640px; margin: auto; padding: 8px 0 20px; }
.rune-mark { width: 58px; height: 58px; margin: 0 auto 6px; color: #c9a6ff; opacity: .9; animation: spinSlow 46s linear infinite; }
.rune-mark svg { width: 100%; height: 100%; }
.rune-mark.small { width: 44px; height: 44px; margin-bottom: 6px; }
@keyframes spinSlow { to { transform: rotate(360deg); } }

.game-title {
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(40px, 11.5vw, 76px);
  font-weight: 400; letter-spacing: .1em; line-height: .94;
  color: #f6ecdc;
  text-shadow: 0 0 30px rgba(180,120,255,.32), 0 4px 18px rgba(0,0,0,.75);
  animation: titleGlow 6s ease-in-out infinite;
}
.game-title span {
  display: block;
  font-size: .78em;
  letter-spacing: .22em;
  color: #d8b7ff;
  text-shadow: 0 0 24px rgba(190,120,255,.55);
}
@keyframes titleGlow { 50% { text-shadow: 0 0 44px rgba(200,140,255,.5), 0 4px 18px rgba(0,0,0,.75); } }
.game-sub {
  font-size: 10px; letter-spacing: 6px; text-transform: uppercase;
  color: #ffc98b; margin-top: 10px; opacity: .9;
  text-shadow: 0 0 12px rgba(255,160,80,.4);
}
.game-pitch {
  font-family: Georgia, serif; font-style: italic;
  font-size: clamp(12px, 3.3vw, 15px); line-height: 1.65;
  color: #c7b7dd; max-width: 470px; margin: 18px auto 0;
}
.primary-btn {
  margin-top: 22px; min-height: 52px; padding: 0 30px;
  display: inline-flex; align-items: center; gap: 12px;
  border-radius: 30px;
  font-size: 14px; font-weight: 700; letter-spacing: 1.6px; text-transform: uppercase;
  color: #1a0d26;
  background: linear-gradient(140deg, #ffe3b0 0%, #ffb96a 45%, #e98a4e 100%);
  border: 1px solid #fff0d2;
  box-shadow: 0 0 26px rgba(255,150,70,.32), 0 8px 24px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.7);
  transition: transform .12s, box-shadow .2s;
  touch-action: manipulation;
}
.primary-btn svg { width: 19px; height: 19px; }
.primary-btn:active { transform: scale(.97); box-shadow: 0 0 18px rgba(255,150,70,.45), 0 4px 12px rgba(0,0,0,.5); }
.control-cards { display: flex; justify-content: center; gap: 8px; margin-top: 26px; flex-wrap: wrap; }
.ctrl {
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  min-width: 92px; padding: 9px 10px 8px;
  border-radius: 10px;
  background: rgba(20,12,36,.5);
  border: 1px solid rgba(180,140,255,.16);
}
.ctrl-ico { color: #e0b0ff; font-size: 13px; line-height: 1; margin-bottom: 2px; }
.ctrl b { font-size: 9.5px; letter-spacing: 1.2px; text-transform: uppercase; color: #efe3ff; font-weight: 700; }
.ctrl em { font-style: normal; font-size: 8.5px; color: #9b8bb4; }
.footnote { margin-top: 14px; font-size: 8.5px; letter-spacing: .7px; color: rgba(190,175,215,.45); }

/* level up */
.levelup-overlay { align-items: center; justify-content: center; background: rgba(5,3,12,.78); }
.levelup-inner { width: min(100%, 760px); margin: auto; text-align: center; animation: popIn .34s cubic-bezier(.2,1.3,.5,1) both; }
@keyframes popIn { from { opacity: 0; transform: translateY(14px) scale(.97); } }
.levelup-head { margin-bottom: 14px; }
.lv-ornament { color: #ffcb85; font-size: 15px; letter-spacing: 8px; text-shadow: 0 0 16px rgba(255,170,80,.6); }
.levelup-head h2 {
  font-family: Georgia, serif; font-weight: 400; font-size: clamp(25px, 6.2vw, 36px);
  letter-spacing: 1px; color: #f8eedc; margin-top: 2px;
  text-shadow: 0 0 24px rgba(190,130,255,.4);
}
.levelup-head h2 span { color: #ffce8d; }
.levelup-head p { font-size: 9.5px; letter-spacing: 3.4px; text-transform: uppercase; color: #b9a6d4; margin-top: 4px; }

.cards { display: flex; flex-direction: column; gap: 9px; margin-top: 6px; }
@media (min-width: 720px) and (min-height: 480px), (orientation: landscape) and (min-height: 430px) {
  .cards { flex-direction: row; gap: 12px; }
  .card { flex: 1 1 0; flex-direction: column; text-align: center; padding: 18px 14px 15px; }
  .card .card-icon { margin: 0 auto 10px; width: 54px; height: 54px; }
  .card .card-tag { margin: 0 auto 4px; }
  .card .card-desc { font-size: 10.5px; }
  .card .rank-pips { justify-content: center; margin-top: 9px; }
}

.card {
  position: relative;
  display: flex; align-items: center; gap: 13px;
  width: 100%; text-align: left;
  padding: 12px 15px;
  border-radius: 14px;
  background:
    linear-gradient(145deg, rgba(43,29,70,.94), rgba(16,10,29,.96));
  border: 1px solid rgba(178,140,255,.26);
  box-shadow: 0 10px 28px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,255,255,.05);
  cursor: pointer;
  transition: transform .13s, border-color .18s, box-shadow .18s;
  animation: cardIn .4s cubic-bezier(.2,1.2,.5,1) both;
  touch-action: manipulation;
}
.card:nth-child(2) { animation-delay: .06s; }
.card:nth-child(3) { animation-delay: .12s; }
@keyframes cardIn { from { opacity: 0; transform: translateY(16px); } }
.card:hover, .card:focus-visible {
  border-color: rgba(255,200,140,.72);
  box-shadow: 0 0 0 1px rgba(255,190,120,.18), 0 12px 34px rgba(0,0,0,.5), 0 0 30px rgba(190,130,255,.18);
  transform: translateY(-2px);
  outline: none;
}
.card:active { transform: scale(.985); }
.card::before {
  content: ""; position: absolute; inset: 0; border-radius: 14px;
  background: radial-gradient(90% 70% at 20% 0%, color-mix(in srgb, var(--card-c, #a97cff) 18%, transparent), transparent 70%);
  pointer-events: none;
}
.card-icon {
  flex: 0 0 48px; width: 48px; height: 48px; border-radius: 12px;
  display: grid; place-items: center;
  color: var(--card-c, #c9aaff);
  background: radial-gradient(circle at 50% 40%, rgba(255,255,255,.08), rgba(10,6,20,.7));
  border: 1px solid color-mix(in srgb, var(--card-c, #a97cff) 40%, transparent);
  box-shadow: inset 0 0 14px color-mix(in srgb, var(--card-c, #a97cff) 20%, transparent);
}
.card-icon svg { width: 28px; height: 28px; }
.card-body { flex: 1; min-width: 0; }
.card-tag {
  display: inline-block; font-size: 7.5px; font-weight: 800; letter-spacing: 1.5px;
  text-transform: uppercase; padding: 2px 6px; border-radius: 4px; margin-bottom: 4px;
  color: #181022; background: var(--card-c, #c9aaff);
}
.card-tag.upgrade { color: #1c1204; background: #ffc87d; }
.card-tag.boon { color: #061612; background: #8fe0b3; }
.card-name {
  font-family: Georgia, serif; font-size: 16px; letter-spacing: .2px;
  color: #f7edde; line-height: 1.15;
}
.card-name em { font-style: normal; font-size: 10px; letter-spacing: 1px; color: #ffcf95; margin-left: 5px; }
.card-desc { font-size: 10px; line-height: 1.45; color: #b9a9cf; margin-top: 3px; }
.card-desc b { color: #ffd9b0; font-weight: 600; }
.rank-pips { display: flex; gap: 3px; margin-top: 5px; }
.rank-pips i { width: 12px; height: 3px; border-radius: 2px; background: rgba(190,160,240,.18); }
.rank-pips i.on { background: var(--card-c, #c9aaff); box-shadow: 0 0 6px var(--card-c, #c9aaff); }
.card-key {
  position: absolute; right: 8px; top: 7px;
  font-size: 8px; color: rgba(220,200,245,.32); font-weight: 700;
}
.card-hint { margin-top: 13px; font-size: 8.5px; letter-spacing: 1.6px; color: rgba(200,180,230,.38); text-transform: uppercase; }

/* pause */
.pause-screen { background: rgba(4,2,10,.78); }
.pause-inner { text-align: center; max-width: 440px; width: 100%; margin: auto; }
.pause-inner h2 { font-family: Georgia, serif; font-weight: 400; font-size: 34px; letter-spacing: 2px; color: #f5ead9; }
.pause-stats { margin-top: 14px; display: flex; justify-content: center; gap: 18px; flex-wrap: wrap; }
.pause-stats div { font-size: 9px; letter-spacing: 1.2px; text-transform: uppercase; color: #9f8fb8; display: flex; flex-direction: column; gap: 2px; }
.pause-stats b { font-family: Georgia, serif; font-size: 21px; font-weight: 400; color: #ffe2b3; letter-spacing: 0; }
.pause-buttons { margin-top: 22px; display: flex; flex-direction: column; gap: 9px; align-items: center; }
.small-btn { margin-top: 0; min-height: 46px; font-size: 12px; padding: 0 26px; }
.ghost-btn {
  min-height: 38px; padding: 0 20px; border-radius: 22px;
  border: 1px solid rgba(190,160,255,.25);
  font-size: 10px; letter-spacing: 1.6px; text-transform: uppercase; color: #a998c4;
  transition: background .15s, color .15s;
}
.ghost-btn:active { background: rgba(160,120,240,.14); color: #e8dcff; }
.loadout { margin-top: 24px; display: flex; flex-wrap: wrap; gap: 7px; justify-content: center; }
.loadout .lo {
  display: flex; align-items: center; gap: 5px; padding: 5px 9px 5px 6px;
  border-radius: 8px; background: rgba(25,16,44,.65); border: 1px solid rgba(180,140,255,.15);
  font-size: 9px; color: #c7b7dd;
}
.loadout .lo svg { width: 15px; height: 15px; color: var(--c, #c9aaff); }
