// ── Emberwitch audio: tiny WebAudio synth, no external assets ──────────────
let ctx = null
let master = null
let ambient = null
let muted = false
let noiseBuf = null
const last = new Map()

function makeNoise(ac) {
  const len = ac.sampleRate * 1.4
  const buf = ac.createBuffer(1, len, ac.sampleRate)
  const data = buf.getChannelData(0)
  let v = 0
  for (let i = 0; i < len; i++) {
    v = v * 0.94 + (Math.random() * 2 - 1) * 0.06
    data[i] = v * 3.2
  }
  return buf
}

export function initAudio() {
  if (ctx) {
    if (ctx.state === 'suspended') ctx.resume()
    return
  }
  const AC = window.AudioContext || window.webkitAudioContext
  if (!AC) return
  ctx = new AC()
  master = ctx.createGain()
  master.gain.value = muted ? 0 : 0.5
  master.connect(ctx.destination)
  noiseBuf = makeNoise(ctx)
}

export function setMuted(v) {
  muted = v
  if (master && ctx) master.gain.setTargetAtTime(muted ? 0 : 0.5, ctx.currentTime, 0.08)
  try { localStorage.setItem('emberwitch.muted', v ? '1' : '0') } catch {}
}
export function isMuted() { return muted }
export function loadMuted() {
  try { muted = localStorage.getItem('emberwitch.muted') === '1' } catch {}
  return muted
}

function tone({ type = 'sine', f0 = 440, f1 = f0, dur = 0.15, vol = 0.1, delay = 0, filter = 0 }) {
  if (!ctx || muted) return
  const t = ctx.currentTime + delay
  const o = ctx.createOscillator()
  const g = ctx.createGain()
  o.type = type
  o.frequency.setValueAtTime(Math.max(20, f0), t)
  o.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur)
  g.gain.setValueAtTime(0.0001, t)
  g.gain.exponentialRampToValueAtTime(vol, t + 0.008)
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
  let node = o
  if (filter) {
    const bq = ctx.createBiquadFilter()
    bq.type = 'lowpass'
    bq.frequency.value = filter
    node.connect(bq); node = bq
  }
  node.connect(g)
  g.connect(master)
  o.start(t)
  o.stop(t + dur + 0.02)
}

function noise({ dur = 0.2, vol = 0.08, freq = 900, q = 0.8, type = 'bandpass', delay = 0, sweep = 0 }) {
  if (!ctx || muted || !noiseBuf) return
  const t = ctx.currentTime + delay
  const s = ctx.createBufferSource()
  s.buffer = noiseBuf
  const bq = ctx.createBiquadFilter()
  bq.type = type
  bq.frequency.setValueAtTime(freq, t)
  if (sweep) bq.frequency.exponentialRampToValueAtTime(Math.max(60, sweep), t + dur)
  bq.Q.value = q
  const g = ctx.createGain()
  g.gain.setValueAtTime(0.0001, t)
  g.gain.exponentialRampToValueAtTime(vol, t + 0.012)
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
  s.connect(bq); bq.connect(g); g.connect(master)
  s.start(t)
  s.stop(t + dur + 0.05)
}

function gate(name, ms) {
  const now = performance.now()
  if ((last.get(name) || 0) + ms > now) return false
  last.set(name, now)
  return true
}

export function sfx(name) {
  if (!ctx || muted) return
  switch (name) {
    case 'shoot':
      if (!gate('shoot', 70)) return
      tone({ type: 'triangle', f0: 680, f1: 250, dur: 0.11, vol: 0.055 })
      noise({ dur: 0.06, vol: 0.018, freq: 2200 })
      break
    case 'hit':
      if (!gate('hit', 45)) return
      noise({ dur: 0.07, vol: 0.035, freq: 1400, q: 1.2 })
      break
    case 'kill':
      if (!gate('kill', 60)) return
      tone({ type: 'square', f0: 190, f1: 58, dur: 0.16, vol: 0.05, filter: 900 })
      noise({ dur: 0.12, vol: 0.03, freq: 500, sweep: 160 })
      break
    case 'hurt':
      tone({ type: 'sawtooth', f0: 210, f1: 72, dur: 0.3, vol: 0.11, filter: 900 })
      noise({ dur: 0.2, vol: 0.05, freq: 320, sweep: 120 })
      break
    case 'dash':
      noise({ dur: 0.24, vol: 0.06, freq: 320, sweep: 1900, q: 0.6 })
      break
    case 'pickup':
      if (!gate('pickup', 40)) return
      tone({ type: 'sine', f0: 940, f1: 1420, dur: 0.08, vol: 0.03 })
      break
    case 'heal':
      tone({ type: 'sine', f0: 520, f1: 780, dur: 0.2, vol: 0.05 })
      tone({ type: 'sine', f0: 780, f1: 1040, dur: 0.22, vol: 0.035, delay: 0.09 })
      break
    case 'level':
      [523, 659, 784, 1046].forEach((f, i) => tone({ type: 'sine', f0: f, f1: f * 1.005, dur: 0.5, vol: 0.075, delay: i * 0.09 }))
      noise({ dur: 0.5, vol: 0.02, freq: 2800, sweep: 5200 })
      break
    case 'card':
      tone({ type: 'triangle', f0: 720, f1: 990, dur: 0.1, vol: 0.05 })
      break
    case 'nova':
      noise({ dur: 0.5, vol: 0.07, freq: 4200, sweep: 500, q: 1.4 })
      tone({ type: 'sine', f0: 1200, f1: 220, dur: 0.4, vol: 0.04 })
      break
    case 'chain':
      noise({ dur: 0.18, vol: 0.05, freq: 3600, sweep: 1200, q: 2 })
      tone({ type: 'square', f0: 1400, f1: 260, dur: 0.14, vol: 0.028 })
      break
    case 'meteor':
      tone({ type: 'sawtooth', f0: 120, f1: 34, dur: 0.8, vol: 0.1, filter: 500 })
      noise({ dur: 0.7, vol: 0.09, freq: 380, sweep: 90, q: 0.5 })
      break
    case 'lob':
      tone({ type: 'sine', f0: 210, f1: 520, dur: 0.22, vol: 0.04 })
      break
    case 'siphon':
      tone({ type: 'sawtooth', f0: 160, f1: 520, dur: 0.5, vol: 0.04, filter: 1200 })
      break
    case 'ward':
      tone({ type: 'sine', f0: 340, f1: 680, dur: 0.35, vol: 0.05 })
      tone({ type: 'sine', f0: 680, f1: 1020, dur: 0.3, vol: 0.03, delay: 0.05 })
      break
    case 'boss':
      tone({ type: 'sawtooth', f0: 74, f1: 42, dur: 1.6, vol: 0.13, filter: 320 })
      tone({ type: 'sawtooth', f0: 112, f1: 62, dur: 1.4, vol: 0.06, filter: 500, delay: 0.1 })
      noise({ dur: 1.2, vol: 0.04, freq: 180, sweep: 90 })
      break
    case 'bossdown':
      tone({ type: 'sawtooth', f0: 160, f1: 30, dur: 1.8, vol: 0.14, filter: 700 })
      noise({ dur: 1.5, vol: 0.08, freq: 900, sweep: 80 })
      break
    case 'win':
      [392, 523, 659, 784, 1046, 1318].forEach((f, i) => tone({ type: 'sine', f0: f, f1: f, dur: 0.8, vol: 0.07, delay: i * 0.13 }))
      break
    case 'die':
      [330, 262, 196, 147].forEach((f, i) => tone({ type: 'triangle', f0: f, f1: f * 0.98, dur: 0.7, vol: 0.08, delay: i * 0.16 }))
      break
    case 'click':
      tone({ type: 'sine', f0: 620, f1: 880, dur: 0.06, vol: 0.04 })
      break
    default:
      break
  }
}

// slow, breathing ambient bed
export function startAmbient() {
  if (!ctx || ambient) return
  const g = ctx.createGain()
  g.gain.value = 0.0001
  g.gain.exponentialRampToValueAtTime(0.055, ctx.currentTime + 3)
  g.connect(master)
  const rev = ctx.createConvolver()
  // simple generated impulse for space
  const len = ctx.sampleRate * 2.2
  const ir = ctx.createBuffer(2, len, ctx.sampleRate)
  for (let ch = 0; ch < 2; ch++) {
    const d = ir.getChannelData(ch)
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2.6)
  }
  rev.buffer = ir
  const wet = ctx.createGain(); wet.gain.value = 0.5
  g.connect(rev); rev.connect(wet); wet.connect(master)

  const drone = []
  ;[55, 82.5, 110, 164.8].forEach((f, i) => {
    const o = ctx.createOscillator()
    o.type = i % 2 ? 'triangle' : 'sine'
    o.frequency.value = f
    o.detune.value = (i - 1.5) * 7
    const og = ctx.createGain()
    og.gain.value = i === 0 ? 0.5 : 0.11
    o.connect(og); og.connect(g)
    o.start()
    drone.push(o)
  })
  // slow filter sweep on wind
  const wind = ctx.createBufferSource()
  wind.buffer = noiseBuf
  wind.loop = true
  const lp = ctx.createBiquadFilter()
  lp.type = 'lowpass'; lp.frequency.value = 420; lp.Q.value = 0.5
  const wg = ctx.createGain(); wg.gain.value = 0.18
  wind.connect(lp); lp.connect(wg); wg.connect(g)
  wind.start()
  const lfo = ctx.createOscillator()
  const lfoG = ctx.createGain(); lfoG.gain.value = 160
  lfo.frequency.value = 0.055
  lfo.connect(lfoG); lfoG.connect(lp.frequency)
  lfo.start()

  ambient = { g, drone, wind, lfo }
}

export function stopAmbient() {
  if (!ambient || !ctx) return
  const a = ambient
  ambient = null
  try {
    a.g.gain.cancelScheduledValues(ctx.currentTime)
    a.g.gain.setTargetAtTime(0.0001, ctx.currentTime, 0.4)
    setTimeout(() => {
      try { a.drone.forEach((o) => o.stop()); a.wind.stop(); a.lfo.stop() } catch {}
    }, 1400)
  } catch {}
}

// ── Emberwitch input: twin virtual sticks, mouse + keyboard ────────────────
const STICK_RADIUS = 54
const DEAD = 0.14

export class Input {
  constructor(canvas) {
    this.canvas = canvas
    this.keys = new Set()
    this.moveStick = { id: null, ox: 0, oy: 0, x: 0, y: 0, dx: 0, dy: 0, mag: 0, active: false }
    this.aimStick = { id: null, ox: 0, oy: 0, x: 0, y: 0, dx: 0, dy: 0, mag: 0, active: false }
    this.mouse = { x: 0, y: 0, down: false, active: false, inside: false }
    this.dashQueued = false
    this.usedTouch = false
    this.firstMove = false
    this.onDashButton = null

    canvas.addEventListener('pointerdown', (e) => this.onDown(e))
    window.addEventListener('pointermove', (e) => this.onMove(e), { passive: false })
    window.addEventListener('pointerup', (e) => this.onUp(e))
    window.addEventListener('pointercancel', (e) => this.onUp(e))
    canvas.addEventListener('contextmenu', (e) => e.preventDefault())
    window.addEventListener('keydown', (e) => this.onKeyDown(e))
    window.addEventListener('keyup', (e) => this.keys.delete(e.code))
    window.addEventListener('blur', () => this.reset())
    document.addEventListener('visibilitychange', () => { if (document.hidden) this.reset() })
  }

  onDown(e) {
    if (e.target !== this.canvas) return
    e.preventDefault()
    const w = this.canvas.clientWidth, h = this.canvas.clientHeight
    const x = e.clientX, y = e.clientY
    this.mouse.inside = true

    if (e.pointerType === 'mouse') {
      this.mouse.x = x; this.mouse.y = y
      if (e.button === 0) this.mouse.down = true
      if (e.button === 2) this.queueDash()
      return
    }
    this.usedTouch = true
    if (y < h * 0.22 && x > w * 0.55) return // top-right HUD area
    const isMove = x < w * 0.5
    const stick = isMove ? this.moveStick : this.aimStick
    if (stick.id !== null) return
    stick.id = e.pointerId
    stick.ox = x; stick.oy = y
    stick.x = x; stick.y = y
    stick.dx = 0; stick.dy = 0; stick.mag = 0; stick.active = true
    if (isMove) this.firstMove = true
  }

  onMove(e) {
    if (e.pointerType === 'mouse') {
      this.mouse.x = e.clientX
      this.mouse.y = e.clientY
      this.mouse.inside = true
      return
    }
    if (e.pointerId === this.moveStick.id) this.updateStick(this.moveStick, e.clientX, e.clientY)
    else if (e.pointerId === this.aimStick.id) this.updateStick(this.aimStick, e.clientX, e.clientY)
  }

  updateStick(stick, x, y) {
    let dx = x - stick.ox, dy = y - stick.oy
    const d = Math.hypot(dx, dy)
    if (d > STICK_RADIUS) {
      // drag the base along so the stick never gets stuck at its edge
      stick.ox += dx * (1 - STICK_RADIUS / d)
      stick.oy += dy * (1 - STICK_RADIUS / d)
      dx = x - stick.ox; dy = y - stick.oy
    }
    const mag = Math.min(1, Math.hypot(dx, dy) / (STICK_RADIUS * 0.82))
    stick.x = x; stick.y = y
    stick.dx = dx; stick.dy = dy; stick.mag = mag
  }

  onUp(e) {
    if (e.pointerType === 'mouse') {
      if (e.button === 0) this.mouse.down = false
      return
    }
    if (e.pointerId === this.moveStick.id) this.clearStick(this.moveStick)
    else if (e.pointerId === this.aimStick.id) this.clearStick(this.aimStick)
  }

  clearStick(s) {
    s.id = null; s.active = false; s.mag = 0; s.dx = 0; s.dy = 0
  }

  onKeyDown(e) {
    const k = e.code
    if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(k)) e.preventDefault()
    if (e.repeat) return
    this.keys.add(k)
    if (k === 'Space' || k === 'ShiftLeft' || k === 'ShiftRight') this.queueDash()
  }

  queueDash() { this.dashQueued = true }
  consumeDash() { const v = this.dashQueued; this.dashQueued = false; return v }

  reset() {
    this.keys.clear()
    this.mouse.down = false
    this.clearStick(this.moveStick)
    this.clearStick(this.aimStick)
  }

  get moveVec() {
    let x = 0, y = 0
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y -= 1
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y += 1
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1
    if (x || y) {
      const d = Math.hypot(x, y)
      return { x: x / d, y: y / d, mag: 1 }
    }
    const s = this.moveStick
    if (s.active && s.mag > DEAD) {
      const d = Math.hypot(s.dx, s.dy) || 1
      const m = Math.min(1, (s.mag - DEAD) / (1 - DEAD))
      return { x: s.dx / d, y: s.dy / d, mag: m }
    }
    return { x: 0, y: 0, mag: 0 }
  }

  get aimVec() {
    const s = this.aimStick
    if (s.active && s.mag > DEAD) {
      const d = Math.hypot(s.dx, s.dy) || 1
      const m = Math.min(1, (s.mag - DEAD) / (1 - DEAD))
      return { x: s.dx / d, y: s.dy / d, mag: m, active: true }
    }
    return { x: 0, y: 0, mag: 0, active: false }
  }

  get firingMouse() { return this.mouse.down }
}

// ── Emberwitch renderer: hand-drawn canvas art, no image assets ────────────
import { SPELLS, BOONS } from './content.js'

const TAU = Math.PI * 2

export const WORLD = { w: 2000, h: 2000 }

// deterministic rng
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function rgba(hex, a) {
  const h = hex.replace('#', '')
  const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16)
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`
}

function glow(ctx, x, y, r, color, alpha = 0.6) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r)
  g.addColorStop(0, rgba(color, alpha))
  g.addColorStop(0.45, rgba(color, alpha * 0.34))
  g.addColorStop(1, rgba(color, 0))
  ctx.fillStyle = g
  ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill()
}

function shadow(ctx, x, y, rx, ry, alpha = 0.32) {
  ctx.save()
  ctx.fillStyle = `rgba(4,2,8,${alpha})`
  ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, TAU); ctx.fill()
  ctx.restore()
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath()
  ctx.moveTo(x + r, y)
  ctx.arcTo(x + w, y, x + w, y + h, r)
  ctx.arcTo(x + w, y + h, x, y + h, r)
  ctx.arcTo(x, y + h, x, y, r)
  ctx.arcTo(x, y, x + w, y, r)
  ctx.closePath()
}

// ── ground ─────────────────────────────────────────────────────────────────
function makeGround() {
  const c = document.createElement('canvas')
  c.width = WORLD.w; c.height = WORLD.h
  const g = c.getContext('2d')
  const rnd = mulberry32(137)

  const base = g.createLinearGradient(0, 0, WORLD.w, WORLD.h)
  base.addColorStop(0, '#101d18')
  base.addColorStop(0.5, '#0c1714')
  base.addColorStop(1, '#0a1211')
  g.fillStyle = base
  g.fillRect(0, 0, WORLD.w, WORLD.h)

  // broad mossy patches
  for (let i = 0; i < 90; i++) {
    const x = rnd() * WORLD.w, y = rnd() * WORLD.h, r = 60 + rnd() * 240
    const hue = rnd()
    const col = hue > 0.7 ? '#173026' : hue > 0.35 ? '#12251d' : '#0d1a17'
    const gr = g.createRadialGradient(x, y, 0, x, y, r)
    gr.addColorStop(0, rgba(col, 0.55)); gr.addColorStop(1, rgba(col, 0))
    g.fillStyle = gr
    g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill()
  }

  // winding dirt paths
  const paths = [
    [[120, 1900], [500, 1400], [860, 1130], [1000, 1000]],
    [[1880, 260], [1500, 640], [1200, 860], [1000, 1000]],
    [[180, 260], [620, 520], [860, 810], [1000, 1000]],
  ]
  for (const pts of paths) {
    g.save()
    g.lineCap = 'round'; g.lineJoin = 'round'
    g.strokeStyle = 'rgba(38,31,22,.55)'; g.lineWidth = 92
    g.beginPath(); g.moveTo(pts[0][0], pts[0][1])
    for (let i = 1; i < pts.length; i++) g.quadraticCurveTo(pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1])
    g.stroke()
    g.strokeStyle = 'rgba(61,48,34,.30)'; g.lineWidth = 58
    g.stroke()
    g.strokeStyle = 'rgba(95,74,48,.10)'; g.lineWidth = 20
    g.stroke()
    g.restore()
  }

  // ritual clearing
  const cx = 1000, cy = 1000
  const clear = g.createRadialGradient(cx, cy, 40, cx, cy, 330)
  clear.addColorStop(0, 'rgba(92,76,48,.32)')
  clear.addColorStop(0.55, 'rgba(52,44,32,.22)')
  clear.addColorStop(1, 'rgba(20,30,25,0)')
  g.fillStyle = clear
  g.beginPath(); g.arc(cx, cy, 330, 0, TAU); g.fill()

  g.save()
  g.translate(cx, cy)
  g.strokeStyle = 'rgba(145,120,190,.17)'; g.lineWidth = 3
  g.beginPath(); g.arc(0, 0, 176, 0, TAU); g.stroke()
  g.strokeStyle = 'rgba(145,120,190,.13)'; g.lineWidth = 1.5
  g.beginPath(); g.arc(0, 0, 152, 0, TAU); g.stroke()
  // runes
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU
    g.save(); g.rotate(a); g.translate(0, -164)
    g.fillStyle = 'rgba(178,150,220,.22)'
    g.beginPath(); g.moveTo(0, -7); g.lineTo(5, 0); g.lineTo(0, 8); g.lineTo(-4, 2); g.closePath(); g.fill()
    g.restore()
  }
  // inner sigil
  g.strokeStyle = 'rgba(170,140,220,.14)'; g.lineWidth = 1.5
  for (let i = 0; i < 6; i++) {
    const a1 = (i / 6) * TAU, a2 = ((i + 2) / 6) * TAU
    g.beginPath()
    g.moveTo(Math.cos(a1) * 80, Math.sin(a1) * 80)
    g.lineTo(Math.cos(a2) * 80, Math.sin(a2) * 80)
    g.stroke()
  }
  g.restore()

  // ring of standing stones around clearing
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU + 0.22
    const x = cx + Math.cos(a) * 220 + (rnd() - 0.5) * 22
    const y = cy + Math.sin(a) * 220 + (rnd() - 0.5) * 22
    const w = 20 + rnd() * 16, h = 32 + rnd() * 30
    g.save(); g.translate(x, y); g.rotate((rnd() - 0.5) * 0.4)
    g.fillStyle = 'rgba(3,6,6,.34)'
    g.beginPath(); g.ellipse(0, h * 0.42, w * 0.9, 8, 0, 0, TAU); g.fill()
    g.fillStyle = '#242b2a'
    g.beginPath()
    g.moveTo(-w / 2, h / 2); g.lineTo(-w / 2 + 3, -h / 2)
    g.lineTo(w / 2 - 4, -h / 2 + 2); g.lineTo(w / 2, h / 2)
    g.closePath(); g.fill()
    g.fillStyle = 'rgba(70,85,78,.4)'
    g.beginPath(); g.moveTo(-w / 2 + 4, h / 2); g.lineTo(-w / 2 + 5, -h / 2 + 3); g.lineTo(-2, -h / 2 + 3); g.lineTo(-3, h / 2); g.closePath(); g.fill()
    g.strokeStyle = 'rgba(150,180,140,.16)'; g.lineWidth = 1.5
    g.beginPath(); g.moveTo(0, -h / 2 + 8); g.lineTo(0, -h / 2 + 20); g.moveTo(-6, -h / 2 + 14); g.lineTo(6, -h / 2 + 14); g.stroke()
    g.restore()
  }

  // grass tufts
  for (let i = 0; i < 2400; i++) {
    const x = rnd() * WORLD.w, y = rnd() * WORLD.h
    const nearCircle = Math.hypot(x - cx, y - cy) < 200
    if (nearCircle) continue
    const h = 3 + rnd() * 8
    const lean = (rnd() - 0.5) * 5
    g.strokeStyle = rnd() > 0.7 ? 'rgba(90,140,95,.30)' : 'rgba(55,100,70,.28)'
    g.lineWidth = 0.9 + rnd() * 0.8
    g.beginPath()
    g.moveTo(x, y)
    g.quadraticCurveTo(x + lean * 0.5, y - h * 0.6, x + lean, y - h)
    g.stroke()
    if (rnd() > 0.65) {
      g.beginPath()
      g.moveTo(x + 2, y)
      g.quadraticCurveTo(x + 2 - lean * 0.4, y - h * 0.4, x + 2 - lean, y - h * 0.7)
      g.stroke()
    }
  }

  // fallen leaves
  for (let i = 0; i < 500; i++) {
    const x = rnd() * WORLD.w, y = rnd() * WORLD.h
    g.save(); g.translate(x, y); g.rotate(rnd() * TAU)
    g.fillStyle = rnd() > 0.5 ? 'rgba(86,92,48,.22)' : 'rgba(112,70,45,.18)'
    g.beginPath(); g.ellipse(0, 0, 2.6, 1.2, 0, 0, TAU); g.fill()
    g.restore()
  }

  // mushrooms and glowcaps
  for (let i = 0; i < 150; i++) {
    const x = rnd() * WORLD.w, y = rnd() * WORLD.h
    if (Math.hypot(x - cx, y - cy) < 190) continue
    const big = rnd() > 0.82
    const s = big ? 1.5 : 0.7 + rnd() * 0.6
    const teal = rnd() > 0.55
    const cap = teal ? '#4fb8a8' : '#9a6ad6'
    glow(g, x, y - 3 * s, 16 * s, cap, teal ? 0.16 : 0.2)
    g.fillStyle = 'rgba(190,205,185,.5)'
    g.fillRect(x - 1.1 * s, y - 3 * s, 2.2 * s, 6 * s)
    g.fillStyle = cap
    g.beginPath(); g.ellipse(x, y - 3.5 * s, 5.4 * s, 3.2 * s, 0, Math.PI, TAU); g.fill()
    g.fillStyle = 'rgba(255,255,255,.45)'
    g.beginPath(); g.arc(x - 1.6 * s, y - 5.4 * s, 0.8 * s, 0, TAU); g.fill()
  }

  // crystals
  for (let i = 0; i < 32; i++) {
    const x = rnd() * WORLD.w, y = rnd() * WORLD.h
    if (Math.hypot(x - cx, y - cy) < 260) continue
    const s = 5 + rnd() * 10
    glow(g, x, y, s * 2.6, '#7ee6ff', 0.13)
    g.fillStyle = 'rgba(96,180,200,.38)'
    g.beginPath(); g.moveTo(x, y - s * 2); g.lineTo(x + s * 0.42, y - s * 0.3); g.lineTo(x, y + s * 0.4); g.lineTo(x - s * 0.42, y - s * 0.3); g.closePath(); g.fill()
    g.fillStyle = 'rgba(190,245,255,.35)'
    g.beginPath(); g.moveTo(x, y - s * 1.7); g.lineTo(x + s * 0.2, y - s * 0.5); g.lineTo(x, y - s * 0.2); g.closePath(); g.fill()
  }

  // rocks
  for (let i = 0; i < 120; i++) {
    const x = rnd() * WORLD.w, y = rnd() * WORLD.h
    if (Math.hypot(x - cx, y - cy) < 200) continue
    const s = 3 + rnd() * 8
    g.fillStyle = 'rgba(40,48,45,.55)'
    g.beginPath(); g.ellipse(x, y, s, s * 0.62, rnd() * TAU, 0, TAU); g.fill()
    g.fillStyle = 'rgba(86,98,90,.16)'
    g.beginPath(); g.ellipse(x - s * 0.15, y - s * 0.2, s * 0.55, s * 0.3, 0, 0, TAU); g.fill()
  }

  // bones
  for (let i = 0; i < 26; i++) {
    const x = rnd() * WORLD.w, y = rnd() * WORLD.h
    if (Math.hypot(x - cx, y - cy) < 210) continue
    g.save(); g.translate(x, y); g.rotate(rnd() * TAU)
    g.strokeStyle = 'rgba(196,186,158,.20)'; g.lineWidth = 2.2
    g.beginPath(); g.moveTo(-6, 0); g.lineTo(7, 2); g.stroke()
    g.beginPath(); g.arc(-7, 0, 2, 0, TAU); g.stroke()
    g.beginPath(); g.arc(-7, 3, 2, 0, TAU); g.stroke()
    g.restore()
  }

  // dead trees, mostly near the border
  const treeAt = (x, y, s) => {
    g.save(); g.translate(x, y); g.scale(s, s)
    g.fillStyle = 'rgba(3,5,5,.4)'
    g.beginPath(); g.ellipse(8, 4, 22, 7, 0, 0, TAU); g.fill()
    g.strokeStyle = '#1a201e'; g.lineWidth = 9; g.lineCap = 'round'
    g.beginPath(); g.moveTo(0, 6); g.quadraticCurveTo(-3, -20, 2, -46); g.stroke()
    g.lineWidth = 5
    g.beginPath(); g.moveTo(0, -18); g.quadraticCurveTo(-18, -32, -27, -50); g.stroke()
    g.beginPath(); g.moveTo(0, -26); g.quadraticCurveTo(17, -38, 25, -58); g.stroke()
    g.beginPath(); g.moveTo(-1, -34); g.quadraticCurveTo(-10, -50, -7, -64); g.stroke()
    g.lineWidth = 2.5
    g.beginPath(); g.moveTo(-27, -50); g.lineTo(-37, -54); g.moveTo(-27, -50); g.lineTo(-31, -62); g.stroke()
    g.beginPath(); g.moveTo(25, -58); g.lineTo(36, -63); g.moveTo(25, -58); g.lineTo(30, -71); g.stroke()
    g.strokeStyle = 'rgba(110,130,110,.12)'; g.lineWidth = 1.5
    g.beginPath(); g.moveTo(1, 4); g.quadraticCurveTo(-1, -20, 2, -44); g.stroke()
    g.restore()
  }
  for (let i = 0; i < 54; i++) {
    const edge = rnd()
    let x, y
    if (edge < 0.25) { x = 30 + rnd() * 80; y = rnd() * WORLD.h }
    else if (edge < 0.5) { x = WORLD.w - 30 - rnd() * 80; y = rnd() * WORLD.h }
    else if (edge < 0.75) { x = rnd() * WORLD.w; y = 30 + rnd() * 80 }
    else { x = rnd() * WORLD.w; y = WORLD.h - 30 - rnd() * 80 }
    treeAt(x, y, 0.9 + rnd() * 0.8)
  }
  for (let i = 0; i < 14; i++) {
    const x = 250 + rnd() * (WORLD.w - 500), y = 250 + rnd() * (WORLD.h - 500)
    if (Math.hypot(x - cx, y - cy) < 340) continue
    treeAt(x, y, 0.7 + rnd() * 0.55)
  }

  // border brambles + darkness
  g.save()
  g.strokeStyle = 'rgba(8,14,12,.9)'; g.lineWidth = 16
  g.strokeRect(6, 6, WORLD.w - 12, WORLD.h - 12)
  g.strokeStyle = 'rgba(30,44,34,.6)'; g.lineWidth = 6
  g.strokeRect(20, 20, WORLD.w - 40, WORLD.h - 40)
  const edgeGrad = g.createRadialGradient(cx, cy, 700, cx, cy, 1180)
  edgeGrad.addColorStop(0, 'rgba(3,6,7,0)')
  edgeGrad.addColorStop(1, 'rgba(2,4,5,.78)')
  g.fillStyle = edgeGrad
  g.fillRect(0, 0, WORLD.w, WORLD.h)
  g.restore()

  // ambient static mote sprinkles
  for (let i = 0; i < 700; i++) {
    const x = rnd() * WORLD.w, y = rnd() * WORLD.h
    g.fillStyle = rnd() > 0.5 ? 'rgba(160,230,180,.12)' : 'rgba(200,160,255,.10)'
    g.beginPath(); g.arc(x, y, 0.6 + rnd() * 1.2, 0, TAU); g.fill()
  }

  return c
}

// ── renderer ───────────────────────────────────────────────────────────────
export class Renderer {
  constructor(canvas) {
    this.canvas = canvas
    this.ctx = canvas.getContext('2d', { alpha: false })
    this.dpr = 1
    this.w = 0; this.h = 0
    this.ground = makeGround()
    this.motes = []
    for (let i = 0; i < 34; i++) {
      this.motes.push({
        x: Math.random(), y: Math.random(),
        vy: 0.006 + Math.random() * 0.012,
        vx: (Math.random() - 0.5) * 0.004,
        r: 0.7 + Math.random() * 1.6,
        p: Math.random() * TAU,
        hue: Math.random() > 0.55 ? 'teal' : 'gold',
      })
    }
    this.resize()
  }

  resize() {
    const c = this.canvas
    const w = c.clientWidth || window.innerWidth
    const h = c.clientHeight || window.innerHeight
    this.dpr = Math.min(2, window.devicePixelRatio || 1)
    this.w = w; this.h = h
    c.width = Math.round(w * this.dpr)
    c.height = Math.round(h * this.dpr)
  }

  draw(game, input, now, dt) {
    const ctx = this.ctx
    const { w, h, dpr } = this
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, w, h)
    ctx.fillStyle = '#080610'
    ctx.fillRect(0, 0, w, h)

    const shakeX = (Math.random() - 0.5) * game.shake
    const shakeY = (Math.random() - 0.5) * game.shake
    const camX = game.camera.x, camY = game.camera.y
    const ox = w / 2 - camX + shakeX
    const oy = h / 2 - camY + shakeY

    ctx.save()
    ctx.translate(ox, oy)

    // ground
    const sx = Math.max(0, camX - w / 2 - 20), sy = Math.max(0, camY - h / 2 - 20)
    const sw = Math.min(WORLD.w - sx, w + 40), sh = Math.min(WORLD.h - sy, h + 40)
    if (sw > 0 && sh > 0) ctx.drawImage(this.ground, sx, sy, sw, sh, sx, sy, sw, sh)

    // zones + ground effects
    for (const z of game.zones) this.drawZone(ctx, z, now)
    this.drawGroundEffects(ctx, game, now)

    // pickups
    for (const p of game.pickups) this.drawPickup(ctx, p, now)

    // entities sorted by y
    const drawables = []
    for (const e of game.enemies) drawables.push({ y: e.y, kind: 'e', e })
    drawables.push({ y: game.player.y, kind: 'p' })
    drawables.sort((a, b) => a.y - b.y)
    for (const d of drawables) {
      if (d.kind === 'p') this.drawPlayer(ctx, game, now)
      else this.drawEnemy(ctx, d.e, now, game)
    }

    // projectiles, effects, texts
    for (const p of game.projectiles) this.drawProjectile(ctx, p, now)
    this.drawTopEffects(ctx, game, now)
    this.drawParticles(ctx, game, now)
    this.drawTexts(ctx, game)

    ctx.restore()

    // ── screen-space atmosphere ──
    this.drawAtmosphere(ctx, game, w, h)
    if (game.hurtFlash > 0.01) {
      const a = Math.min(0.30, game.hurtFlash * 0.30)
      const grd = ctx.createRadialGradient(w / 2, h / 2, h * 0.2, w / 2, h / 2, h * 0.72)
      grd.addColorStop(0, 'rgba(160,10,30,0)')
      grd.addColorStop(1, `rgba(190,15,40,${a})`)
      ctx.fillStyle = grd
      ctx.fillRect(0, 0, w, h)
    }

    if (game.state === 'playing' || game.state === 'levelup' || game.state === 'paused') {
      this.drawSticks(ctx, input, game, w, h)
      if (!input.usedTouch && input.mouse.inside) this.drawCrosshair(ctx, input, w, h)
    }

    this.drawMotes(ctx, w, h, dt, now)
  }

  // ── atmosphere ──
  drawAtmosphere(ctx, game, w, h) {
    const px = w / 2 + (game.player.x - game.camera.x)
    const py = h / 2 + (game.player.y - game.camera.y)
    const g = ctx.createRadialGradient(px, py, 60, px, py, Math.max(w, h) * 0.62)
    g.addColorStop(0, 'rgba(6,3,14,0)')
    g.addColorStop(0.62, 'rgba(6,3,14,.10)')
    g.addColorStop(1, 'rgba(4,2,10,.56)')
    ctx.fillStyle = g
    ctx.fillRect(0, 0, w, h)

    // faint moonwash from the top
    const m = ctx.createLinearGradient(0, 0, 0, h * 0.55)
    m.addColorStop(0, 'rgba(120,110,200,.055)')
    m.addColorStop(1, 'rgba(120,110,200,0)')
    ctx.fillStyle = m
    ctx.fillRect(0, 0, w, h)
  }

  drawMotes(ctx, w, h, dt, now) {
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    for (const m of this.motes) {
      m.y -= m.vy * dt
      m.x += m.vx * dt
      if (m.y < -0.03) { m.y = 1.03; m.x = Math.random() }
      if (m.x < -0.03) m.x = 1.03
      if (m.x > 1.03) m.x = -0.03
      const a = 0.18 + 0.22 * Math.sin(now * 2 + m.p)
      const x = m.x * w, y = m.y * h
      const col = m.hue === 'teal' ? '60,220,190' : '255,180,100'
      const rad = m.r * 5
      const g = ctx.createRadialGradient(x, y, 0, x, y, rad)
      g.addColorStop(0, `rgba(${col},${a})`); g.addColorStop(1, `rgba(${col},0)`)
      ctx.fillStyle = g
      ctx.beginPath(); ctx.arc(x, y, rad, 0, TAU); ctx.fill()
    }
    ctx.restore()
  }

  // ── player ──
  drawPlayer(ctx, game, now) {
    const p = game.player
    const moving = Math.hypot(p.vx, p.vy) > 8
    const bob = moving ? Math.sin(now * 13) * 2.2 : Math.sin(now * 2.4) * 1.1
    const lean = Math.sin(now * 6.5) * (moving ? 0.06 : 0.015)
    const face = Math.cos(p.facing) < 0 ? -1 : 1
    const staffGlow = Math.max(0.35, 1 - p.attackTimer / Math.max(0.001, p.attackCd))

    // shadow
    shadow(ctx, p.x, p.y + 16, 16, 6, 0.4)

    // magic circle
    ctx.save()
    ctx.translate(p.x, p.y + 17)
    ctx.scale(1, 0.42)
    ctx.rotate(now * 0.35)
    ctx.strokeStyle = 'rgba(168,120,255,.26)'; ctx.lineWidth = 1.6
    ctx.beginPath(); ctx.arc(0, 0, 30, 0, TAU); ctx.stroke()
    ctx.setLineDash([4, 9]); ctx.strokeStyle = 'rgba(168,120,255,.20)'
    ctx.beginPath(); ctx.arc(0, 0, 35, 0, TAU); ctx.stroke()
    ctx.setLineDash([])
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU
      ctx.fillStyle = 'rgba(200,160,255,.30)'
      ctx.beginPath(); ctx.arc(Math.cos(a) * 30, Math.sin(a) * 30, 2, 0, TAU); ctx.fill()
    }
    ctx.restore()

    // aim rune at feet
    if (game.state === 'playing') {
      ctx.save()
      ctx.globalCompositeOperation = 'lighter'
      const ax = p.x + Math.cos(p.aim) * 26, ay = p.y + 14 + Math.sin(p.aim) * 8
      glow(ctx, ax, ay, 13, '#ff9a4d', 0.25)
      ctx.restore()
    }

    ctx.save()
    ctx.translate(p.x, p.y + bob)
    ctx.scale(face, 1)
    ctx.rotate(lean)
    if (p.invuln > 0 && Math.floor(now * 18) % 2 === 0) ctx.globalAlpha = 0.55

    // cloak / body
    const sway = Math.sin(now * 7) * 2.4
    const cloak = ctx.createLinearGradient(0, -20, 0, 18)
    cloak.addColorStop(0, '#3a2266'); cloak.addColorStop(0.5, '#2a1749'); cloak.addColorStop(1, '#1b0f31')
    ctx.fillStyle = cloak
    ctx.beginPath()
    ctx.moveTo(-9, -14)
    ctx.quadraticCurveTo(-14, 0, -13 + sway * 0.3, 14)
    ctx.quadraticCurveTo(-6, 18, 0, 16)
    ctx.quadraticCurveTo(7, 18, 13 - sway * 0.3, 14)
    ctx.quadraticCurveTo(14, 0, 9, -14)
    ctx.closePath(); ctx.fill()
    ctx.strokeStyle = 'rgba(120,80,180,.55)'; ctx.lineWidth = 1.2; ctx.stroke()

    // hem trim
    ctx.strokeStyle = 'rgba(170,130,240,.45)'; ctx.lineWidth = 1.3
    ctx.beginPath()
    ctx.moveTo(-11, 12); ctx.quadraticCurveTo(-5, 16, 0, 14.5); ctx.quadraticCurveTo(6, 16, 11, 12)
    ctx.stroke()

    // little boots
    ctx.fillStyle = '#150c22'
    ctx.beginPath(); ctx.ellipse(-5, 16, 4, 2.6, 0.2, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.ellipse(5, 16, 4, 2.6, -0.2, 0, TAU); ctx.fill()

    // belt
    ctx.fillStyle = '#1a1029'
    ctx.fillRect(-8, 2, 16, 3)
    ctx.fillStyle = '#ffcf80'
    ctx.beginPath(); ctx.arc(0, 3.5, 1.9, 0, TAU); ctx.fill()

    // staff (held on right)
    ctx.save()
    ctx.translate(11, 3)
    ctx.rotate(-0.22 + Math.sin(now * 7) * 0.03)
    ctx.strokeStyle = '#4a2f22'; ctx.lineWidth = 2.4; ctx.lineCap = 'round'
    ctx.beginPath(); ctx.moveTo(0, 8); ctx.quadraticCurveTo(3, -12, 5, -30); ctx.stroke()
    ctx.strokeStyle = '#6b4630'; ctx.lineWidth = 1.1
    ctx.beginPath(); ctx.moveTo(0.5, 8); ctx.quadraticCurveTo(3, -12, 5, -29); ctx.stroke()
    // prongs
    ctx.strokeStyle = '#7a5836'; ctx.lineWidth = 1.6
    ctx.beginPath(); ctx.moveTo(5, -30); ctx.quadraticCurveTo(1, -35, -1, -37); ctx.moveTo(5, -30); ctx.quadraticCurveTo(9, -35, 11, -36); ctx.stroke()
    // orb
    const orbR = 5 + staffGlow * 2
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    glow(ctx, 5, -33, 24, '#ff9a4d', 0.24 + staffGlow * 0.2)
    glow(ctx, 5, -33, 11, '#ffd29a', 0.45 + staffGlow * 0.3)
    ctx.fillStyle = `rgba(255,220,170,${0.65 + staffGlow * 0.3})`
    ctx.beginPath(); ctx.arc(5, -33, orbR * 0.62, 0, TAU); ctx.fill()
    ctx.restore()
    ctx.restore()

    // left hand
    ctx.fillStyle = '#e8cfc2'
    ctx.beginPath(); ctx.arc(-10, 2, 3, 0, TAU); ctx.fill()

    // head
    ctx.fillStyle = '#f0d8cc'
    ctx.beginPath(); ctx.ellipse(0, -18, 7.4, 7.8, 0, 0, TAU); ctx.fill()
    // hair
    ctx.fillStyle = '#d6c2ef'
    ctx.beginPath()
    ctx.moveTo(-7.6, -20)
    ctx.quadraticCurveTo(-8, -11, -6, -9)
    ctx.quadraticCurveTo(-7, -14, -4, -17)
    ctx.closePath(); ctx.fill()
    ctx.beginPath()
    ctx.moveTo(7.4, -21)
    ctx.quadraticCurveTo(8.4, -12, 6, -9)
    ctx.quadraticCurveTo(7.4, -15, 4, -18)
    ctx.closePath(); ctx.fill()
    // eyes
    ctx.fillStyle = '#2a1733'
    ctx.beginPath(); ctx.ellipse(-2.7, -17, 1.0, 1.5, 0, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.ellipse(2.7, -17, 1.0, 1.5, 0, 0, TAU); ctx.fill()
    ctx.fillStyle = 'rgba(255,180,120,.9)'
    ctx.beginPath(); ctx.arc(-2.7, -17.4, 0.4, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.arc(2.7, -17.4, 0.4, 0, TAU); ctx.fill()

    // witch hat
    const hatSway = Math.sin(now * 2.6) * 0.05
    ctx.save()
    ctx.translate(0, -24)
    ctx.rotate(hatSway)
    ctx.fillStyle = '#241338'
    ctx.beginPath(); ctx.ellipse(0, 1, 15.5, 4.4, 0, 0, TAU); ctx.fill()
    ctx.strokeStyle = '#5b3a8d'; ctx.lineWidth = 1
    ctx.beginPath(); ctx.ellipse(0, 1, 15.5, 4.4, 0, 0, TAU); ctx.stroke()
    const hat = ctx.createLinearGradient(-8, -28, 8, 2)
    hat.addColorStop(0, '#4b2c80'); hat.addColorStop(0.55, '#311b56'); hat.addColorStop(1, '#1f1038')
    ctx.fillStyle = hat
    ctx.beginPath()
    ctx.moveTo(-10.5, 1)
    ctx.quadraticCurveTo(-7, -10, 1, -21)
    ctx.quadraticCurveTo(-5, -25, -6, -30)
    ctx.quadraticCurveTo(8, -22, 12, -4)
    ctx.quadraticCurveTo(4, 2, -10.5, 1)
    ctx.closePath(); ctx.fill()
    ctx.strokeStyle = 'rgba(140,95,210,.6)'; ctx.lineWidth = 0.9; ctx.stroke()
    // band + buckle
    ctx.strokeStyle = '#e0a95f'; ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(-9.6, -4.4); ctx.quadraticCurveTo(0, -1.4, 10.5, -6.2); ctx.stroke()
    ctx.fillStyle = '#ffd591'; ctx.fillRect(-1.5, -5.4, 3, 3)
    // little star charm
    ctx.fillStyle = 'rgba(255,220,160,.8)'
    for (let i = 0; i < 4; i++) {
      ctx.save(); ctx.rotate(i * TAU / 4); ctx.beginPath(); ctx.ellipse(0, -29 - 2, 0.9, 2.4, 0, 0, TAU); ctx.fill(); ctx.restore()
    }
    ctx.restore()
    ctx.restore()

    // shield ward bubble
    if (p.shield > 0.5) {
      ctx.save()
      ctx.globalCompositeOperation = 'lighter'
      const pulse = 1 + Math.sin(now * 4) * 0.025
      const r = 29 * pulse
      const g = ctx.createRadialGradient(p.x, p.y - 6, r * 0.55, p.x, p.y - 6, r)
      g.addColorStop(0, 'rgba(140,190,255,0)')
      g.addColorStop(0.75, 'rgba(140,190,255,.08)')
      g.addColorStop(1, 'rgba(150,200,255,.24)')
      ctx.fillStyle = g
      ctx.beginPath(); ctx.arc(p.x, p.y - 6, r, 0, TAU); ctx.fill()
      ctx.strokeStyle = `rgba(180,215,255,${0.3 + 0.15 * Math.sin(now * 5)})`; ctx.lineWidth = 1.3
      ctx.beginPath(); ctx.arc(p.x, p.y - 6, r, 0, TAU); ctx.stroke()
      ctx.setLineDash([3, 7]); ctx.lineDashOffset = -now * 10
      ctx.beginPath(); ctx.arc(p.x, p.y - 6, r - 4, 0, TAU); ctx.stroke()
      ctx.restore()
    }

    // familiars
    if (game.spells.familiar) {
      const rank = game.spells.familiar
      const count = rank >= 4 ? 2 : 1
      for (let i = 0; i < count; i++) {
        const a = now * 1.5 + i * Math.PI
        const fx = p.x + Math.cos(a) * 46
        const fy = p.y - 6 + Math.sin(a) * 22
        ctx.save()
        ctx.globalCompositeOperation = 'lighter'
        glow(ctx, fx, fy, 24, '#c9a6ff', 0.4)
        glow(ctx, fx, fy, 9, '#fff0ff', 0.5)
        ctx.fillStyle = 'rgba(235,220,255,.92)'
        ctx.beginPath(); ctx.arc(fx, fy, 4.2, 0, TAU); ctx.fill()
        // ears
        ctx.beginPath(); ctx.moveTo(fx - 4, fy - 2); ctx.lineTo(fx - 5.5, fy - 8); ctx.lineTo(fx - 1, fy - 4); ctx.closePath(); ctx.fill()
        ctx.beginPath(); ctx.moveTo(fx + 4, fy - 2); ctx.lineTo(fx + 5.5, fy - 8); ctx.lineTo(fx + 1, fy - 4); ctx.closePath(); ctx.fill()
        ctx.fillStyle = '#3a2060'
        ctx.beginPath(); ctx.arc(fx - 1.4, fy - 0.6, 0.75, 0, TAU); ctx.fill()
        ctx.beginPath(); ctx.arc(fx + 1.4, fy - 0.6, 0.75, 0, TAU); ctx.fill()
        ctx.restore()
      }
    }
  }

  // ── enemies ──
  drawEnemy(ctx, e, now, game) {
    const flying = e.def?.flying
    const bob = flying ? Math.sin(now * 4 + e.seed * 9) * 4 : 0
    const x = e.x, y = e.y + bob
    const elite = e.elite
    const chilled = e.slow > 0

    if (!flying) shadow(ctx, e.x, e.y + e.radius * 0.85, e.radius * 0.95, e.radius * 0.36, 0.34 + (elite ? 0.1 : 0))
    else shadow(ctx, e.x, e.y + e.radius * 0.9, e.radius * 0.7, e.radius * 0.24, 0.18)

    if (elite || e.isBoss) {
      ctx.save()
      ctx.globalCompositeOperation = 'lighter'
      const aura = e.isBoss ? 58 : e.radius * 2.2
      glow(ctx, x, y, aura, e.isBoss ? e.bossColor || '#b06fe0' : '#ffb15e', e.isBoss ? 0.16 : 0.22 + Math.sin(now * 4) * 0.04)
      ctx.restore()
    }

    ctx.save()
    ctx.translate(x, y)
    if (e.flash > 0) ctx.filter = 'brightness(2.6) saturate(.3)'
    if (e.type === 'slime') this.drawSlime(ctx, e, now)
    else if (e.type === 'bat') this.drawBat(ctx, e, now)
    else if (e.type === 'skeleton') this.drawSkeleton(ctx, e, now)
    else if (e.type === 'wraith') this.drawWraith(ctx, e, now)
    else if (e.type === 'imp') this.drawImp(ctx, e, now)
    else if (e.type === 'hound') this.drawHound(ctx, e, now)
    else if (e.type === 'boss') this.drawBoss(ctx, e, now)
    ctx.filter = 'none'
    ctx.restore()

    if (chilled) {
      ctx.save()
      ctx.globalCompositeOperation = 'lighter'
      glow(ctx, x, y, e.radius * 1.7, '#8fe1ff', 0.16)
      ctx.restore()
    }

    // telegraphs for windups
    if (e.windup > 0) {
      const t = 1 - e.windup / e.windupMax
      ctx.save()
      ctx.globalCompositeOperation = 'lighter'
      ctx.strokeStyle = `rgba(255,90,90,${0.25 + t * 0.4})`
      ctx.lineWidth = 2
      ctx.beginPath(); ctx.arc(e.x, e.y + 4, e.radius + 14 + (1 - t) * 10, 0, TAU); ctx.stroke()
      ctx.fillStyle = `rgba(255,60,70,${0.04 + t * 0.08})`
      ctx.beginPath(); ctx.arc(e.x, e.y + 4, e.radius + 14, 0, TAU); ctx.fill()
      ctx.restore()
    }

    // hp bar
    if (e.hp < e.maxHp && !e.isBoss) {
      const w = e.radius * 2.1
      const yy = y - e.radius - 12
      ctx.fillStyle = 'rgba(4,2,8,.72)'
      roundRect(ctx, x - w / 2 - 1, yy - 1, w + 2, 5, 2.5); ctx.fill()
      ctx.fillStyle = elite ? '#ffc07a' : '#ff6b7f'
      roundRect(ctx, x - w / 2, yy, w * Math.max(0, e.hp / e.maxHp), 3, 1.5); ctx.fill()
    }
    if (elite) {
      ctx.fillStyle = '#ffd79a'
      ctx.font = 'bold 8px ui-sans-serif, system-ui'
      ctx.textAlign = 'center'
      ctx.fillText('ELITE', x, y - e.radius - 18)
      ctx.textAlign = 'left'
    }
  }

  drawSlime(ctx, e, now) {
    const squash = Math.sin(now * 5 + e.seed * 6) * 0.1
    const r = e.radius
    const body = ctx.createRadialGradient(-r * 0.3, -r * 0.5, 1, 0, 0, r * 1.35)
    body.addColorStop(0, '#b6f5a8'); body.addColorStop(0.35, '#6ed47e'); body.addColorStop(1, '#27603c')
    ctx.fillStyle = body
    ctx.beginPath()
    ctx.ellipse(0, 2, r * (1 + squash), r * (0.88 - squash), 0, 0, TAU)
    ctx.fill()
    ctx.strokeStyle = 'rgba(190,255,190,.4)'; ctx.lineWidth = 1; ctx.stroke()
    // gloss
    ctx.fillStyle = 'rgba(255,255,255,.28)'
    ctx.beginPath(); ctx.ellipse(-r * 0.32, -r * 0.34, r * 0.26, r * 0.16, -0.4, 0, TAU); ctx.fill()
    // eyes
    ctx.fillStyle = '#102418'
    ctx.beginPath(); ctx.arc(-r * 0.3, -r * 0.05, 2.1, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.arc(r * 0.3, -r * 0.05, 2.1, 0, TAU); ctx.fill()
    ctx.fillStyle = '#d8ffcf'
    ctx.beginPath(); ctx.arc(-r * 0.34, -r * 0.12, 0.7, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.arc(r * 0.26, -r * 0.12, 0.7, 0, TAU); ctx.fill()
    // mouth
    ctx.strokeStyle = 'rgba(12,30,20,.65)'; ctx.lineWidth = 1
    ctx.beginPath(); ctx.arc(0, r * 0.22, r * 0.26, 0.2, Math.PI - 0.2); ctx.stroke()
  }

  drawBat(ctx, e, now) {
    const flap = Math.sin(now * 16 + e.seed * 7)
    const r = e.radius
    ctx.fillStyle = '#3c2352'
    // wings
    ctx.save()
    ctx.strokeStyle = '#5a3478'; ctx.lineWidth = 1
    ctx.fillStyle = '#432760'
    ctx.beginPath()
    ctx.moveTo(-3, -2)
    ctx.quadraticCurveTo(-r * 2.3, -r * 1.4 - flap * 5, -r * 3.1, -r * 0.1 + flap * 2)
    ctx.quadraticCurveTo(-r * 2, r * 0.2, -r * 1.2, r * 0.4)
    ctx.quadraticCurveTo(-r * 0.5, 1, -2, 2)
    ctx.closePath(); ctx.fill(); ctx.stroke()
    ctx.beginPath()
    ctx.moveTo(3, -2)
    ctx.quadraticCurveTo(r * 2.3, -r * 1.4 - flap * 5, r * 3.1, -r * 0.1 + flap * 2)
    ctx.quadraticCurveTo(r * 2, r * 0.2, r * 1.2, r * 0.4)
    ctx.quadraticCurveTo(r * 0.5, 1, 2, 2)
    ctx.closePath(); ctx.fill(); ctx.stroke()
    ctx.restore()
    // body
    const body = ctx.createRadialGradient(0, -3, 1, 0, 0, r)
    body.addColorStop(0, '#7a4aa8'); body.addColorStop(1, '#2e1a45')
    ctx.fillStyle = body
    ctx.beginPath(); ctx.ellipse(0, 0, r * 0.72, r * 0.9, 0, 0, TAU); ctx.fill()
    // ears
    ctx.fillStyle = '#3a2055'
    ctx.beginPath(); ctx.moveTo(-4, -r * 0.7); ctx.lineTo(-6, -r * 1.35); ctx.lineTo(-1, -r * 0.9); ctx.closePath(); ctx.fill()
    ctx.beginPath(); ctx.moveTo(4, -r * 0.7); ctx.lineTo(6, -r * 1.35); ctx.lineTo(1, -r * 0.9); ctx.closePath(); ctx.fill()
    // eyes
    ctx.fillStyle = '#ff7a8a'
    ctx.beginPath(); ctx.arc(-2.3, -2, 1.4, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.arc(2.3, -2, 1.4, 0, TAU); ctx.fill()
    // fangs
    ctx.fillStyle = '#f3e9d6'
    ctx.beginPath(); ctx.moveTo(-2, 4); ctx.lineTo(-1, 6.2); ctx.lineTo(0, 4); ctx.closePath(); ctx.fill()
    ctx.beginPath(); ctx.moveTo(0.5, 4); ctx.lineTo(1.5, 6.2); ctx.lineTo(2.5, 4); ctx.closePath(); ctx.fill()
  }

  drawSkeleton(ctx, e, now) {
    const r = e.radius
    const step = Math.sin(now * 6 + e.seed * 5)
    ctx.strokeStyle = '#cfc4a8'; ctx.lineWidth = 2.6; ctx.lineCap = 'round'
    // legs
    ctx.beginPath(); ctx.moveTo(-3, 6); ctx.lineTo(-4 + step * 2, 15); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(3, 6); ctx.lineTo(3 - step * 2, 15); ctx.stroke()
    // body
    ctx.strokeStyle = '#e5dbc0'; ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(0, -6); ctx.lineTo(0, 7); ctx.stroke()
    for (let i = 0; i < 3; i++) {
      ctx.beginPath(); ctx.ellipse(0, -2 + i * 3.1, 5.5 - i * 0.5, 2.4, 0, 0, TAU); ctx.stroke()
    }
    // arms
    ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(-4, -3); ctx.quadraticCurveTo(-9, 1, -8, 6); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(4, -3); ctx.quadraticCurveTo(10, 0, 11, 4); ctx.stroke()
    // sword
    ctx.save(); ctx.translate(11, 5); ctx.rotate(-0.5 + step * 0.08)
    ctx.strokeStyle = '#7a5a3c'; ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(0, 2); ctx.lineTo(2, -11); ctx.stroke()
    ctx.strokeStyle = '#b9c4c0'; ctx.lineWidth = 2.4
    ctx.beginPath(); ctx.moveTo(2, -9); ctx.lineTo(3.5, -22); ctx.stroke()
    ctx.fillStyle = '#8a6a44'; ctx.fillRect(-2, -1, 5, 2)
    ctx.restore()
    // skull
    ctx.fillStyle = '#efe5cc'
    ctx.beginPath(); ctx.ellipse(0, -12, 6.4, 7, 0, 0, TAU); ctx.fill()
    ctx.fillStyle = '#efe5cc'
    ctx.beginPath(); ctx.moveTo(-4, -6); ctx.lineTo(-3, -2.5); ctx.lineTo(3, -2.5); ctx.lineTo(4, -6); ctx.closePath(); ctx.fill()
    ctx.fillStyle = '#1b201c'
    ctx.beginPath(); ctx.ellipse(-2.5, -13, 1.8, 2.1, 0.1, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.ellipse(2.6, -13, 1.8, 2.1, -0.1, 0, TAU); ctx.fill()
    ctx.fillStyle = 'rgba(140,255,180,.75)'
    ctx.beginPath(); ctx.arc(-2.5, -13.2, 0.7, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.arc(2.6, -13.2, 0.7, 0, TAU); ctx.fill()
    ctx.strokeStyle = '#5b5548'; ctx.lineWidth = 0.9
    ctx.beginPath(); ctx.moveTo(-2, -7.5); ctx.lineTo(2, -7.5); ctx.stroke()
    for (let i = -1; i <= 1; i++) { ctx.beginPath(); ctx.moveTo(i * 1.8, -8); ctx.lineTo(i * 1.8, -5.5); ctx.stroke() }
  }

  drawWraith(ctx, e, now) {
    const r = e.radius
    const drift = Math.sin(now * 2.2 + e.seed * 4) * 2
    ctx.save()
    ctx.translate(0, drift)
    // tattered cloak
    const grad = ctx.createLinearGradient(0, -r * 1.6, 0, r * 1.4)
    grad.addColorStop(0, 'rgba(110,150,200,.85)')
    grad.addColorStop(0.6, 'rgba(50,85,130,.7)')
    grad.addColorStop(1, 'rgba(20,40,70,0)')
    ctx.fillStyle = grad
    ctx.beginPath()
    ctx.moveTo(-r * 0.8, -r * 0.7)
    ctx.quadraticCurveTo(-r * 1.25, r * 0.2, -r * 0.9, r * 1.25)
    ctx.quadraticCurveTo(-r * 0.45, r * 0.9, -r * 0.2, r * 1.5)
    ctx.quadraticCurveTo(0, r * 1.0, r * 0.25, r * 1.5)
    ctx.quadraticCurveTo(r * 0.5, r * 0.9, r * 0.95, r * 1.25)
    ctx.quadraticCurveTo(r * 1.25, r * 0.2, r * 0.8, -r * 0.7)
    ctx.quadraticCurveTo(0, -r * 1.9, -r * 0.8, -r * 0.7)
    ctx.fill()
    // hood
    ctx.fillStyle = 'rgba(25,48,75,.95)'
    ctx.beginPath(); ctx.ellipse(0, -r * 0.55, r * 0.8, r * 0.95, 0, 0, TAU); ctx.fill()
    ctx.fillStyle = 'rgba(10,20,35,.95)'
    ctx.beginPath(); ctx.ellipse(0, -r * 0.45, r * 0.56, r * 0.68, 0, 0, TAU); ctx.fill()
    // eyes
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    glow(ctx, -r * 0.25, -r * 0.6, 7, '#8fe7ff', 0.6)
    glow(ctx, r * 0.25, -r * 0.6, 7, '#8fe7ff', 0.6)
    ctx.fillStyle = '#e6ffff'
    ctx.beginPath(); ctx.ellipse(-r * 0.25, -r * 0.6, 1.6, 2.4, 0, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.ellipse(r * 0.25, -r * 0.6, 1.6, 2.4, 0, 0, TAU); ctx.fill()
    ctx.restore()
    // grasping hands
    ctx.strokeStyle = 'rgba(190,220,245,.35)'; ctx.lineWidth = 1.4
    ctx.beginPath(); ctx.moveTo(-r * 0.9, r * 0.1); ctx.lineTo(-r * 1.25, r * 0.55); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(r * 0.9, r * 0.1); ctx.lineTo(r * 1.25, r * 0.55); ctx.stroke()
    ctx.restore()
  }

  drawImp(ctx, e, now) {
    const r = e.radius
    const hop = Math.sin(now * 8 + e.seed * 5) * 1.5
    ctx.save(); ctx.translate(0, hop)
    // wings
    const flap = Math.sin(now * 18) * 0.4
    ctx.fillStyle = 'rgba(90,35,30,.8)'
    ctx.beginPath(); ctx.moveTo(-5, -2); ctx.quadraticCurveTo(-r * 2, -r - flap * 6, -r * 2.2, 2); ctx.quadraticCurveTo(-r, 1, -4, 4); ctx.closePath(); ctx.fill()
    ctx.beginPath(); ctx.moveTo(5, -2); ctx.quadraticCurveTo(r * 2, -r - flap * 6, r * 2.2, 2); ctx.quadraticCurveTo(r, 1, 4, 4); ctx.closePath(); ctx.fill()
    // body
    const body = ctx.createRadialGradient(-2, -5, 1, 0, 0, r * 1.2)
    body.addColorStop(0, '#ffb07a'); body.addColorStop(0.45, '#e2613c'); body.addColorStop(1, '#6e241f')
    ctx.fillStyle = body
    ctx.beginPath(); ctx.ellipse(0, 1, r * 0.72, r * 0.92, 0, 0, TAU); ctx.fill()
    // legs
    ctx.strokeStyle = '#7a2c24'; ctx.lineWidth = 2.2
    ctx.beginPath(); ctx.moveTo(-3, 9); ctx.lineTo(-4, 14); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(3, 9); ctx.lineTo(4, 14); ctx.stroke()
    // horns
    ctx.fillStyle = '#2b1722'
    ctx.beginPath(); ctx.moveTo(-4, -r * 0.6); ctx.quadraticCurveTo(-9, -r * 1.5, -3, -r * 1.3); ctx.quadraticCurveTo(-2, -r, 0, -r * 0.7); ctx.closePath(); ctx.fill()
    ctx.beginPath(); ctx.moveTo(4, -r * 0.6); ctx.quadraticCurveTo(9, -r * 1.5, 3, -r * 1.3); ctx.quadraticCurveTo(2, -r, 0, -r * 0.7); ctx.closePath(); ctx.fill()
    // eyes
    ctx.fillStyle = '#fff1a8'
    ctx.beginPath(); ctx.ellipse(-2.4, -2.5, 1.6, 1.9, 0.2, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.ellipse(2.4, -2.5, 1.6, 1.9, -0.2, 0, TAU); ctx.fill()
    // grin
    ctx.strokeStyle = '#3a0d10'; ctx.lineWidth = 1
    ctx.beginPath(); ctx.arc(0, 2.4, 3.2, 0.15, Math.PI - 0.15); ctx.stroke()
    // fire in palms
    ctx.save(); ctx.globalCompositeOperation = 'lighter'
    glow(ctx, -r * 0.9, 5, 9, '#ff8a3d', 0.4)
    glow(ctx, r * 0.9, 5, 9, '#ff8a3d', 0.4)
    ctx.restore()
    ctx.restore()
  }

  drawHound(ctx, e, now) {
    const r = e.radius
    const step = Math.sin(now * 12 + e.seed * 3)
    ctx.strokeStyle = '#3d4d26'; ctx.lineWidth = 2
    // legs
    for (const [lx, off] of [[-7, 0], [-4, 1], [4, -1], [8, 0]]) {
      ctx.beginPath(); ctx.moveTo(lx, 5); ctx.lineTo(lx + step * 2 * (off || 1), 14); ctx.stroke()
    }
    // body
    const body = ctx.createLinearGradient(-r, -r, r, r)
    body.addColorStop(0, '#6f8a3e'); body.addColorStop(0.5, '#4c6430'); body.addColorStop(1, '#26351c')
    ctx.fillStyle = body
    ctx.beginPath(); ctx.ellipse(0, 0, r * 1.15, r * 0.7, 0, 0, TAU); ctx.fill()
    // thorns along back
    ctx.fillStyle = '#30401f'
    for (let i = -2; i <= 2; i++) {
      ctx.beginPath(); ctx.moveTo(i * 6, -r * 0.55); ctx.lineTo(i * 6 + 2, -r * 0.95); ctx.lineTo(i * 6 + 4, -r * 0.5); ctx.closePath(); ctx.fill()
    }
    // head
    ctx.fillStyle = '#586f33'
    ctx.beginPath(); ctx.ellipse(r * 0.95, -3, r * 0.5, r * 0.4, 0.2, 0, TAU); ctx.fill()
    ctx.fillStyle = '#2b351b'
    ctx.beginPath(); ctx.ellipse(r * 1.32, -2, r * 0.24, r * 0.2, 0.2, 0, TAU); ctx.fill()
    // eye
    ctx.fillStyle = '#ffec8a'
    ctx.beginPath(); ctx.arc(r * 1.05, -5, 1.5, 0, TAU); ctx.fill()
    // briar glow
    ctx.save(); ctx.globalCompositeOperation = 'lighter'
    glow(ctx, 0, 0, r * 1.5, '#a9e06a', 0.1)
    ctx.restore()
  }

  drawBoss(ctx, e, now) {
    const r = e.radius
    if (e.bossKind === 'warden') {
      const sway = Math.sin(now * 1.4) * 0.03
      ctx.save(); ctx.rotate(sway)
      // roots
      ctx.strokeStyle = '#344a2a'; ctx.lineWidth = 7; ctx.lineCap = 'round'
      for (let i = 0; i < 4; i++) {
        const a = 0.4 + i * 0.55
        ctx.beginPath(); ctx.moveTo(0, r * 0.4); ctx.quadraticCurveTo(Math.cos(a) * r * 0.8, r * 1.1, Math.cos(a) * r * 1.2, r * 1.25); ctx.stroke()
      }
      // trunk
      const trunk = ctx.createLinearGradient(-r, 0, r, 0)
      trunk.addColorStop(0, '#3c2c22'); trunk.addColorStop(0.5, '#5f4630'); trunk.addColorStop(1, '#2e221b')
      ctx.fillStyle = trunk
      ctx.beginPath()
      ctx.moveTo(-r * 0.55, r * 0.9)
      ctx.quadraticCurveTo(-r * 0.75, -r * 0.4, -r * 0.35, -r * 0.95)
      ctx.quadraticCurveTo(0, -r * 1.2, r * 0.35, -r * 0.95)
      ctx.quadraticCurveTo(r * 0.75, -r * 0.4, r * 0.55, r * 0.9)
      ctx.closePath(); ctx.fill()
      // bark lines
      ctx.strokeStyle = 'rgba(30,20,14,.6)'; ctx.lineWidth = 1.5
      for (let i = -2; i <= 2; i++) { ctx.beginPath(); ctx.moveTo(i * r * 0.18, -r * 0.7); ctx.quadraticCurveTo(i * r * 0.22, 0, i * r * 0.2, r * 0.8); ctx.stroke() }
      // antler branches
      ctx.strokeStyle = '#4b3925'; ctx.lineWidth = 5; ctx.lineCap = 'round'
      for (const s of [-1, 1]) {
        ctx.beginPath(); ctx.moveTo(s * r * 0.3, -r * 0.8); ctx.quadraticCurveTo(s * r * 0.9, -r * 1.35, s * r * 0.75, -r * 1.75); ctx.stroke()
        ctx.lineWidth = 3
        ctx.beginPath(); ctx.moveTo(s * r * 0.55, -r * 1.15); ctx.quadraticCurveTo(s * r * 1.1, -r * 1.45, s * r * 1.3, -r * 1.4); ctx.stroke()
        ctx.beginPath(); ctx.moveTo(s * r * 0.7, -r * 1.55); ctx.lineTo(s * r * 0.55, -r * 1.9); ctx.stroke()
        ctx.lineWidth = 5
      }
      // glowing heart
      ctx.save(); ctx.globalCompositeOperation = 'lighter'
      glow(ctx, 0, -r * 0.15, 30 + Math.sin(now * 3) * 4, '#a4ff8a', 0.45)
      ctx.fillStyle = '#d7ffb0'
      ctx.beginPath(); ctx.ellipse(0, -r * 0.15, 6, 9, 0, 0, TAU); ctx.fill()
      ctx.restore()
      // eyes
      ctx.fillStyle = '#d9ffb0'
      ctx.beginPath(); ctx.ellipse(-r * 0.18, -r * 0.55, 2.6, 1.6, 0.2, 0, TAU); ctx.fill()
      ctx.beginPath(); ctx.ellipse(r * 0.18, -r * 0.55, 2.6, 1.6, -0.2, 0, TAU); ctx.fill()
      // crown of thorns
      ctx.strokeStyle = '#6d7f3a'; ctx.lineWidth = 2
      ctx.beginPath(); ctx.arc(0, -r * 0.92, r * 0.34, Math.PI * 1.05, Math.PI * 1.95); ctx.stroke()
      ctx.restore()
    } else {
      // Hollow King — crowned wraith
      const drift = Math.sin(now * 1.7) * 3
      ctx.save(); ctx.translate(0, drift)
      // cloak
      const grad = ctx.createLinearGradient(0, -r * 1.4, 0, r * 1.5)
      grad.addColorStop(0, 'rgba(120,80,190,.9)')
      grad.addColorStop(0.5, 'rgba(55,32,92,.9)')
      grad.addColorStop(1, 'rgba(15,8,28,0)')
      ctx.fillStyle = grad
      ctx.beginPath()
      ctx.moveTo(-r * 0.5, -r * 0.6)
      ctx.quadraticCurveTo(-r * 1.4, r * 0.2, -r * 1.05, r * 1.4)
      for (let i = 0; i < 4; i++) {
        const x1 = -r * 1.05 + (i + 0.5) * (r * 2.1 / 4)
        ctx.quadraticCurveTo(x1, r * (1.0 + (i % 2) * 0.35), x1 + r * 0.26, r * 1.5)
      }
      ctx.quadraticCurveTo(r * 1.4, r * 0.2, r * 0.5, -r * 0.6)
      ctx.quadraticCurveTo(0, -r * 1.6, -r * 0.5, -r * 0.6)
      ctx.fill()
      // inner void
      ctx.fillStyle = 'rgba(9,4,18,.92)'
      ctx.beginPath(); ctx.ellipse(0, -r * 0.25, r * 0.46, r * 0.68, 0, 0, TAU); ctx.fill()
      // eyes
      ctx.save(); ctx.globalCompositeOperation = 'lighter'
      glow(ctx, -r * 0.2, -r * 0.34, 22, '#c79aff', 0.55)
      glow(ctx, r * 0.2, -r * 0.34, 22, '#c79aff', 0.55)
      ctx.fillStyle = '#f3e4ff'
      ctx.beginPath(); ctx.ellipse(-r * 0.2, -r * 0.34, 3.4, 5, 0.3, 0, TAU); ctx.fill()
      ctx.beginPath(); ctx.ellipse(r * 0.2, -r * 0.34, 3.4, 5, -0.3, 0, TAU); ctx.fill()
      ctx.restore()
      // skeletal hands
      ctx.strokeStyle = 'rgba(220,200,240,.7)'; ctx.lineWidth = 2
      for (const s of [-1, 1]) {
        ctx.beginPath(); ctx.moveTo(s * r * 0.55, r * 0.05); ctx.quadraticCurveTo(s * r * 1.15, r * 0.4, s * r * 1.05, r * 0.8); ctx.stroke()
        for (let f = 0; f < 3; f++) {
          ctx.beginPath(); ctx.moveTo(s * r * 1.05, r * 0.78); ctx.lineTo(s * r * (1.08 + f * 0.05), r * (0.95 + f * 0.04)); ctx.stroke()
        }
      }
      // crown
      const cy = -r * 1.15 + Math.sin(now * 2.4) * 2
      ctx.fillStyle = '#e6bc63'
      ctx.beginPath()
      ctx.moveTo(-r * 0.44, cy + 6)
      ctx.lineTo(-r * 0.5, cy - 12)
      ctx.lineTo(-r * 0.22, cy - 3)
      ctx.lineTo(0, cy - 18)
      ctx.lineTo(r * 0.22, cy - 3)
      ctx.lineTo(r * 0.5, cy - 12)
      ctx.lineTo(r * 0.44, cy + 6)
      ctx.closePath(); ctx.fill()
      ctx.strokeStyle = 'rgba(255,240,190,.6)'; ctx.lineWidth = 1; ctx.stroke()
      ctx.save(); ctx.globalCompositeOperation = 'lighter'
      glow(ctx, 0, cy - 2, 30, '#ffd27a', 0.22)
      ctx.fillStyle = '#ffe9b0'
      for (let i = -1; i <= 1; i++) { ctx.beginPath(); ctx.arc(i * r * 0.28, cy - 1, 1.5, 0, TAU); ctx.fill() }
      ctx.restore()
      ctx.restore()
    }
  }

  // ── projectiles ──
  drawProjectile(ctx, p, now) {
    const trailLen = p.kind === 'enemy' ? 2 : 3
    ctx.save()
    ctx.globalCompositeOperation = p.kind === 'enemy' ? 'source-over' : 'lighter'
    if (p.kind === 'vial') {
      ctx.translate(p.x, p.y)
      ctx.rotate(now * 8)
      ctx.fillStyle = '#88e07a'
      ctx.beginPath(); ctx.moveTo(-3, -7); ctx.lineTo(3, -7); ctx.lineTo(5, 5); ctx.quadraticCurveTo(0, 9, -5, 5); ctx.closePath(); ctx.fill()
      ctx.fillStyle = 'rgba(220,255,190,.5)'
      ctx.beginPath(); ctx.ellipse(-1, 0, 1.3, 2.4, 0.4, 0, TAU); ctx.fill()
    } else if (p.kind === 'enemy') {
      glow(ctx, p.x, p.y, p.r * 4.2, p.color, 0.35)
      ctx.fillStyle = p.color
      ctx.beginPath(); ctx.arc(p.x, p.y, p.r * 0.7, 0, TAU); ctx.fill()
      ctx.fillStyle = 'rgba(255,230,230,.8)'
      ctx.beginPath(); ctx.arc(p.x, p.y, p.r * 0.3, 0, TAU); ctx.fill()
    } else {
      for (let i = trailLen; i > 0; i--) {
        const f = i / trailLen
        glow(ctx, p.x - p.vx * 0.012 * i, p.y - p.vy * 0.012 * i, p.r * (1.5 + f), p.color, 0.10 + (1 - f) * 0.14)
      }
      glow(ctx, p.x, p.y, p.r * 4.4, p.color, 0.4)
      glow(ctx, p.x, p.y, p.r * 1.9, '#fff3d8', 0.55)
      ctx.fillStyle = '#fff6e4'
      ctx.beginPath(); ctx.arc(p.x, p.y, p.r * 0.48, 0, TAU); ctx.fill()
      // spinning sparks
      ctx.strokeStyle = rgba(p.color, 0.55); ctx.lineWidth = 1
      for (let i = 0; i < 2; i++) {
        const a = now * 7 + i * Math.PI
        ctx.beginPath()
        ctx.moveTo(p.x + Math.cos(a) * p.r * 1.1, p.y + Math.sin(a) * p.r * 1.1)
        ctx.lineTo(p.x + Math.cos(a) * p.r * 2.2, p.y + Math.sin(a) * p.r * 2.2)
        ctx.stroke()
      }
    }
    ctx.restore()
  }

  drawPickup(ctx, p, now) {
    const float = Math.sin(now * 3 + p.seed * 8) * 2.4
    if (p.kind === 'heal') {
      ctx.save()
      ctx.globalCompositeOperation = 'lighter'
      glow(ctx, p.x, p.y + float, 22, '#ff6f8a', 0.36)
      ctx.translate(p.x, p.y + float)
      ctx.scale(1, 1)
      ctx.fillStyle = '#ff8fa3'
      ctx.beginPath()
      ctx.moveTo(0, 6)
      ctx.bezierCurveTo(-9, -1, -5, -8, 0, -4)
      ctx.bezierCurveTo(5, -8, 9, -1, 0, 6)
      ctx.fill()
      ctx.fillStyle = 'rgba(255,230,235,.8)'
      ctx.beginPath(); ctx.ellipse(-1.8, -2, 2.4, 1.4, -0.5, 0, TAU); ctx.fill()
      ctx.restore()
    } else {
      ctx.save()
      ctx.globalCompositeOperation = 'lighter'
      glow(ctx, p.x, p.y + float, 14 + p.v * 2, p.kind === 'big' ? '#ffcf7a' : '#a8ffd0', 0.34)
      ctx.translate(p.x, p.y + float)
      ctx.rotate(now * 1.8 + p.seed * 3)
      const s = p.kind === 'big' ? 1.5 : 1
      ctx.fillStyle = p.kind === 'big' ? '#ffd88f' : '#a8f5c8'
      ctx.beginPath(); ctx.moveTo(0, -6 * s); ctx.lineTo(4.2 * s, 0); ctx.lineTo(0, 6 * s); ctx.lineTo(-4.2 * s, 0); ctx.closePath(); ctx.fill()
      ctx.fillStyle = 'rgba(255,255,255,.85)'
      ctx.beginPath(); ctx.moveTo(0, -3.4 * s); ctx.lineTo(2 * s, 0); ctx.lineTo(0, 2 * s); ctx.lineTo(-2 * s, 0); ctx.closePath(); ctx.fill()
      ctx.restore()
    }
  }

  // ── zones ──
  drawZone(ctx, z, now) {
    const fade = Math.min(1, z.life / 0.5)
    ctx.save()
    if (z.type === 'bramble') {
      ctx.globalAlpha = fade
      const g = ctx.createRadialGradient(z.x, z.y, 4, z.x, z.y, z.r)
      g.addColorStop(0, 'rgba(70,130,80,.22)'); g.addColorStop(1, 'rgba(40,90,60,0)')
      ctx.fillStyle = g
      ctx.beginPath(); ctx.arc(z.x, z.y, z.r, 0, TAU); ctx.fill()
      ctx.strokeStyle = 'rgba(130,220,140,.55)'; ctx.lineWidth = 2
      for (let i = 0; i < 9; i++) {
        const a = (i / 9) * TAU + z.seed * 6 + Math.sin(now * 1.5 + i) * 0.1
        const len = z.r * (0.65 + Math.sin(now * 3 + i * 2) * 0.2)
        ctx.beginPath()
        ctx.moveTo(z.x, z.y)
        ctx.quadraticCurveTo(z.x + Math.cos(a + 0.3) * len * 0.5, z.y + Math.sin(a + 0.3) * len * 0.5, z.x + Math.cos(a) * len, z.y + Math.sin(a) * len)
        ctx.stroke()
        ctx.fillStyle = 'rgba(150,240,150,.6)'
        ctx.beginPath(); ctx.arc(z.x + Math.cos(a) * len, z.y + Math.sin(a) * len, 2, 0, TAU); ctx.fill()
      }
    } else if (z.type === 'poison') {
      ctx.globalAlpha = fade
      const g = ctx.createRadialGradient(z.x, z.y, 4, z.x, z.y, z.r)
      g.addColorStop(0, 'rgba(150,230,90,.18)'); g.addColorStop(0.7, 'rgba(90,160,60,.13)'); g.addColorStop(1, 'rgba(50,90,40,0)')
      ctx.fillStyle = g
      ctx.beginPath(); ctx.arc(z.x, z.y, z.r, 0, TAU); ctx.fill()
      ctx.globalCompositeOperation = 'lighter'
      for (let i = 0; i < 7; i++) {
        const t = now * 0.7 + i * 1.7 + z.seed * 9
        const a = i * 2.4 + z.seed * 4
        const rr = z.r * (0.25 + 0.55 * ((t * 0.6) % 1))
        const bx = z.x + Math.cos(a) * rr, by = z.y + Math.sin(a) * rr - ((t * 12) % 18)
        glow(ctx, bx, by, 9, '#b8f27a', 0.16)
      }
    } else if (z.type === 'fire') {
      ctx.globalAlpha = fade
      const g = ctx.createRadialGradient(z.x, z.y, 4, z.x, z.y, z.r)
      g.addColorStop(0, 'rgba(255,140,60,.20)'); g.addColorStop(1, 'rgba(120,30,10,0)')
      ctx.fillStyle = g
      ctx.beginPath(); ctx.arc(z.x, z.y, z.r, 0, TAU); ctx.fill()
      ctx.globalCompositeOperation = 'lighter'
      for (let i = 0; i < 10; i++) {
        const a = i * 2.1 + z.seed * 5
        const rr = z.r * (0.2 + 0.7 * ((i * 0.37 + now * 0.3) % 1))
        const fx = z.x + Math.cos(a) * rr, fy = z.y + Math.sin(a) * rr
        const fl = 3 + Math.sin(now * 9 + i * 3) * 2
        glow(ctx, fx, fy, 12, '#ff9a4d', 0.2)
        ctx.fillStyle = 'rgba(255,210,140,.55)'
        ctx.beginPath(); ctx.ellipse(fx, fy, 1.8, fl, 0, 0, TAU); ctx.fill()
      }
    }
    ctx.restore()
  }

  // ── effects (under entities) ──
  drawGroundEffects(ctx, game, now) {
    ctx.save()
    for (const e of game.effects) {
      if (e.layer !== 'ground') continue
      const t = e.life / e.maxLife
      if (e.type === 'telegraph') {
        const prog = 1 - t
        ctx.save()
        ctx.globalCompositeOperation = 'lighter'
        ctx.strokeStyle = rgba(e.color || '#ff9a4d', 0.5 + prog * 0.35)
        ctx.lineWidth = 2
        ctx.setLineDash([7, 6]); ctx.lineDashOffset = -now * 20
        ctx.beginPath(); ctx.ellipse(e.x, e.y, e.r, e.r * 0.55, 0, 0, TAU); ctx.stroke()
        ctx.setLineDash([])
        ctx.fillStyle = rgba(e.color || '#ff9a4d', 0.06 + prog * 0.10)
        ctx.beginPath(); ctx.ellipse(e.x, e.y, e.r * prog, e.r * 0.55 * prog, 0, 0, TAU); ctx.fill()
        // falling mark
        ctx.restore()
        if (e.type === 'telegraph' && e.extra === 'meteor') {
          const fall = Math.max(0, 1 - t * 2.2)
          const fy = e.y - 380 * fall
          ctx.save()
          ctx.globalCompositeOperation = 'lighter'
          glow(ctx, e.x, fy, 34, '#ff8a3d', 0.5)
          glow(ctx, e.x, fy - 22, 60, '#ff5e2a', 0.18)
          ctx.strokeStyle = 'rgba(255,190,120,.55)'; ctx.lineWidth = 7; ctx.lineCap = 'round'
          ctx.beginPath(); ctx.moveTo(e.x, fy); ctx.lineTo(e.x + 18, fy - 65); ctx.stroke()
          ctx.fillStyle = '#ffd8a8'
          ctx.beginPath(); ctx.arc(e.x, fy, 9, 0, TAU); ctx.fill()
          ctx.restore()
        }
      }
    }
    ctx.restore()
  }

  drawTopEffects(ctx, game, now) {
    ctx.save()
    for (const e of game.effects) {
      if (e.layer === 'ground') continue
      const t = Math.max(0, e.life / e.maxLife)
      if (e.type === 'ring') {
        const p = 1 - t
        const rr = e.r0 + (e.r - e.r0) * (1 - Math.pow(1 - p, 2))
        ctx.save()
        ctx.globalCompositeOperation = 'lighter'
        ctx.strokeStyle = rgba(e.color, 0.75 * t)
        ctx.lineWidth = e.width * t + 1
        ctx.beginPath(); ctx.ellipse(e.x, e.y, rr, rr * (e.flat ? 0.55 : 1), 0, 0, TAU); ctx.stroke()
        ctx.strokeStyle = rgba(e.color, 0.22 * t)
        ctx.lineWidth = e.width * 2.6 * t + 2
        ctx.beginPath(); ctx.ellipse(e.x, e.y, rr, rr * (e.flat ? 0.55 : 1), 0, 0, TAU); ctx.stroke()
        ctx.restore()
      } else if (e.type === 'burst') {
        ctx.save()
        ctx.globalCompositeOperation = 'lighter'
        glow(ctx, e.x, e.y, e.r * (0.4 + (1 - t) * 0.8), e.color, 0.5 * t)
        ctx.restore()
      } else if (e.type === 'lightning') {
        ctx.save()
        ctx.globalCompositeOperation = 'lighter'
        for (let pass = 0; pass < 2; pass++) {
          ctx.strokeStyle = pass === 0 ? rgba(e.color, 0.26 * t) : 'rgba(255,255,255,.85)'
          ctx.lineWidth = pass === 0 ? 7 : 1.8
          ctx.beginPath()
          ctx.moveTo(e.pts[0].x, e.pts[0].y)
          for (let i = 1; i < e.pts.length; i++) ctx.lineTo(e.pts[i].x, e.pts[i].y)
          ctx.stroke()
        }
        for (const p of e.pts) {
          glow(ctx, p.x, p.y, 16, e.color, 0.4 * t)
        }
        ctx.restore()
      } else if (e.type === 'beam') {
        const w = 7 * t
        ctx.save()
        ctx.globalCompositeOperation = 'lighter'
        ctx.strokeStyle = rgba(e.color, 0.18 * t); ctx.lineWidth = w * 3; ctx.lineCap = 'round'
        ctx.beginPath(); ctx.moveTo(e.x1, e.y1); ctx.lineTo(e.x2, e.y2); ctx.stroke()
        ctx.strokeStyle = rgba(e.color, 0.72 * t); ctx.lineWidth = w
        ctx.beginPath(); ctx.moveTo(e.x1, e.y1); ctx.lineTo(e.x2, e.y2); ctx.stroke()
        ctx.strokeStyle = `rgba(255,240,240,${0.85 * t})`; ctx.lineWidth = Math.max(1, w * 0.3)
        ctx.beginPath(); ctx.moveTo(e.x1, e.y1); ctx.lineTo(e.x2, e.y2); ctx.stroke()
        for (let i = 0; i < 5; i++) {
          const k = (now * 1.6 + i * 0.2) % 1
          const px = e.x1 + (e.x2 - e.x1) * k, py = e.y1 + (e.y2 - e.y1) * k
          glow(ctx, px, py, 12, e.color, 0.5 * t)
        }
        ctx.restore()
      } else if (e.type === 'nova') {
        ctx.save()
        ctx.globalCompositeOperation = 'lighter'
        const p = 1 - t
        const rr = e.r * (1 - Math.pow(1 - p, 2))
        ctx.strokeStyle = rgba('#8fe1ff', 0.5 * t); ctx.lineWidth = 20 * t + 2
        ctx.beginPath(); ctx.arc(e.x, e.y, rr, 0, TAU); ctx.stroke()
        ctx.strokeStyle = `rgba(240,252,255,${0.9 * t})`; ctx.lineWidth = 2
        ctx.beginPath(); ctx.arc(e.x, e.y, rr, 0, TAU); ctx.stroke()
        for (let i = 0; i < 12; i++) {
          const a = (i / 12) * TAU
          const rx = e.x + Math.cos(a) * rr * 0.92, ry = e.y + Math.sin(a) * rr * 0.92
          ctx.strokeStyle = `rgba(200,245,255,${0.7 * t})`; ctx.lineWidth = 1.5
          ctx.beginPath(); ctx.moveTo(rx, ry); ctx.lineTo(rx + Math.cos(a) * 14 * t, ry + Math.sin(a) * 14 * t); ctx.stroke()
        }
        ctx.restore()
      } else if (e.type === 'shadowBlast') {
        ctx.save()
        ctx.fillStyle = rgba(e.color, 0.28 * t)
        ctx.beginPath(); ctx.arc(e.x, e.y, e.r * (0.5 + (1 - t) * 0.7), 0, TAU); ctx.fill()
        ctx.restore()
      } else if (e.type === 'levelup') {
        ctx.save()
        ctx.globalCompositeOperation = 'lighter'
        const p = 1 - t
        for (let i = 0; i < 3; i++) {
          const rr = 20 + p * (60 + i * 32)
          ctx.strokeStyle = `rgba(210,170,255,${(1 - p) * 0.5})`
          ctx.lineWidth = 2
          ctx.beginPath(); ctx.arc(e.x, e.y, rr, 0, TAU); ctx.stroke()
        }
        glow(ctx, e.x, e.y, 90 * t + 20, '#c9a6ff', 0.3 * t)
        ctx.restore()
      } else if (e.type === 'spawnRing') {
        ctx.save()
        ctx.globalCompositeOperation = 'lighter'
        const p = 1 - t
        ctx.strokeStyle = rgba(e.color || '#c9a6ff', 0.6 * t); ctx.lineWidth = 2
        ctx.beginPath(); ctx.ellipse(e.x, e.y, e.r * (0.4 + p * 0.8), e.r * (0.4 + p * 0.8) * 0.5, 0, 0, TAU); ctx.stroke()
        ctx.restore()
      }
    }
    ctx.restore()
  }

  drawParticles(ctx, game, now) {
    ctx.save()
    for (const p of game.particles) {
      const t = Math.max(0, p.life / p.maxLife)
      if (p.glow) ctx.globalCompositeOperation = 'lighter'
      else ctx.globalCompositeOperation = 'source-over'
      const a = p.fade === false ? 1 : t
      if (p.shape === 'spark') {
        const len = Math.hypot(p.vx, p.vy) * 0.03
        ctx.strokeStyle = rgba(p.color, a * 0.9)
        ctx.lineWidth = p.size
        ctx.lineCap = 'round'
        ctx.beginPath()
        ctx.moveTo(p.x, p.y)
        ctx.lineTo(p.x - p.vx * 0.02, p.y - p.vy * 0.02)
        ctx.stroke()
      } else if (p.shape === 'leaf') {
        ctx.save()
        ctx.translate(p.x, p.y)
        ctx.rotate(p.rot || 0)
        ctx.fillStyle = rgba(p.color, a * 0.9)
        ctx.beginPath(); ctx.ellipse(0, 0, p.size * 1.7, p.size * 0.7, 0, 0, TAU); ctx.fill()
        ctx.restore()
      } else {
        if (p.glow) {
          glow(ctx, p.x, p.y, p.size * 4.5, p.color, a * 0.3)
        }
        ctx.fillStyle = rgba(p.color, a)
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * (p.shrink === false ? 1 : t * 0.7 + 0.3), 0, TAU); ctx.fill()
      }
    }
    ctx.globalCompositeOperation = 'source-over'
    ctx.restore()
  }

  drawTexts(ctx, game) {
    ctx.save()
    ctx.textAlign = 'center'
    for (const t of game.texts) {
      const a = Math.min(1, t.life / 0.3)
      const pop = t.crit ? 1.25 : 1
      ctx.globalAlpha = a
      ctx.font = `700 ${Math.round(t.size * pop)}px ui-sans-serif, system-ui, -apple-system`
      ctx.lineWidth = 3
      ctx.strokeStyle = 'rgba(8,4,14,.7)'
      ctx.strokeText(t.text, t.x, t.y)
      ctx.fillStyle = t.color
      ctx.fillText(t.text, t.x, t.y)
      if (t.crit) {
        ctx.font = `700 ${Math.round(t.size * 0.55)}px ui-sans-serif, system-ui`
        ctx.fillStyle = '#ffe6b0'
        ctx.fillText('CRIT', t.x, t.y - t.size * 1.05)
      }
    }
    ctx.restore()
  }

  // ── screen-space controls ──
  drawSticks(ctx, input, game, w, h) {
    const rx = Math.min(96, w * 0.22)
    const by = h - Math.max(90, 74 + (parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--safe-b')) || 0) * 0)
    this.drawStick(ctx, input.moveStick, w * 0.5 - Math.min(150, w * 0.3), by, 'move', game)
    this.drawStick(ctx, input.aimStick, w * 0.5 + Math.min(150, w * 0.3), by, 'aim', game)
  }

  drawStick(ctx, stick, bx, by, kind, game) {
    const active = stick.active
    const ox = active ? stick.ox : bx
    const oy = active ? stick.oy : by
    const R = 54
    ctx.save()
    ctx.globalAlpha = active ? 0.9 : 0.5
    // base
    ctx.strokeStyle = active ? 'rgba(205,175,255,.55)' : 'rgba(190,165,230,.24)'
    ctx.lineWidth = 1.2
    ctx.beginPath(); ctx.arc(ox, oy, R, 0, TAU); ctx.stroke()
    ctx.setLineDash([3, 8]); ctx.lineDashOffset = -performance.now() * 0.01
    ctx.strokeStyle = active ? 'rgba(205,175,255,.28)' : 'rgba(190,165,230,.13)'
    ctx.beginPath(); ctx.arc(ox, oy, R - 8, 0, TAU); ctx.stroke()
    ctx.setLineDash([])
    // fill hint
    const g = ctx.createRadialGradient(ox, oy, 0, ox, oy, R)
    g.addColorStop(0, active ? 'rgba(120,80,200,.12)' : 'rgba(120,80,200,.04)')
    g.addColorStop(1, 'rgba(120,80,200,0)')
    ctx.fillStyle = g
    ctx.beginPath(); ctx.arc(ox, oy, R, 0, TAU); ctx.fill()
    // knob
    let kx = ox, ky = oy
    if (active) {
      const d = Math.hypot(stick.dx, stick.dy)
      const cl = Math.min(R - 10, d)
      const a = Math.atan2(stick.dy, stick.dx)
      kx = ox + Math.cos(a) * cl
      ky = oy + Math.sin(a) * cl
    }
    const kg = ctx.createRadialGradient(kx, ky - 5, 0, kx, ky, 25)
    if (kind === 'aim') {
      kg.addColorStop(0, 'rgba(255,210,160,.85)'); kg.addColorStop(0.4, 'rgba(190,120,255,.55)'); kg.addColorStop(1, 'rgba(120,70,200,.12)')
    } else {
      kg.addColorStop(0, 'rgba(210,190,255,.8)'); kg.addColorStop(0.5, 'rgba(140,100,230,.42)'); kg.addColorStop(1, 'rgba(120,70,200,.1)')
    }
    ctx.fillStyle = kg
    ctx.beginPath(); ctx.arc(kx, ky, 22, 0, TAU); ctx.fill()
    ctx.strokeStyle = active ? 'rgba(240,225,255,.7)' : 'rgba(200,180,240,.3)'
    ctx.lineWidth = 1
    ctx.beginPath(); ctx.arc(kx, ky, 22, 0, TAU); ctx.stroke()
    // icon / label
    ctx.globalAlpha = active ? 0.95 : 0.55
    ctx.fillStyle = kind === 'aim' ? 'rgba(255,215,170,.9)' : 'rgba(225,210,255,.9)'
    if (kind === 'aim') {
      ctx.beginPath(); ctx.arc(ox, oy, 2, 0, TAU); ctx.fill()
      ctx.strokeStyle = 'rgba(255,200,150,.4)'; ctx.lineWidth = 1
      for (let i = 0; i < 4; i++) {
        const a = i * Math.PI / 2
        ctx.beginPath(); ctx.moveTo(ox + Math.cos(a) * 11, oy + Math.sin(a) * 11); ctx.lineTo(ox + Math.cos(a) * 17, oy + Math.sin(a) * 17); ctx.stroke()
      }
    } else {
      ctx.strokeStyle = 'rgba(225,210,255,.45)'; ctx.lineWidth = 1.3
      for (let i = 0; i < 4; i++) {
        const a = i * Math.PI / 2 + Math.PI / 4
        ctx.beginPath(); ctx.moveTo(ox + Math.cos(a) * 9, oy + Math.sin(a) * 9); ctx.lineTo(ox + Math.cos(a) * 15, oy + Math.sin(a) * 15); ctx.stroke()
      }
    }
    // cooldown arc for aim (ember)
    if (kind === 'aim' && game && game.state === 'playing') {
      const cd = game.player.attackCd > 0 ? game.player.attackTimer / game.player.attackCd : 0
      if (cd > 0.01) {
        ctx.strokeStyle = 'rgba(255,160,90,.5)'; ctx.lineWidth = 2.5
        ctx.beginPath(); ctx.arc(ox, oy, R + 5, -Math.PI / 2, -Math.PI / 2 + TAU * (1 - cd)); ctx.stroke()
      }
    }
    ctx.restore()
  }

  drawCrosshair(ctx, input, w, h) {
    const x = input.mouse.x, y = input.mouse.y
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    ctx.strokeStyle = 'rgba(255,200,140,.5)'; ctx.lineWidth = 1
    ctx.beginPath(); ctx.arc(x, y, 9, 0, TAU); ctx.stroke()
    for (let i = 0; i < 4; i++) {
      const a = i * Math.PI / 2
      ctx.beginPath(); ctx.moveTo(x + Math.cos(a) * 12, y + Math.sin(a) * 12); ctx.lineTo(x + Math.cos(a) * 17, y + Math.sin(a) * 17); ctx.stroke()
    }
    ctx.fillStyle = 'rgba(255,225,180,.8)'
    ctx.beginPath(); ctx.arc(x, y, 1.5, 0, TAU); ctx.fill()
    ctx.restore()
  }
}

export { rgba, glow }

// ── Emberwitch: run simulation, spells, progression, UI ────────────────────
import { SPELLS, BOONS, ENEMIES, BOSSES, SPELL_ORDER, ROMAN } from './content.js'
import { WORLD } from './render.js'
import { sfx } from './audio.js'

const TAU = Math.PI * 2
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v)
const lerp = (a, b, t) => a + (b - a) * t
const edge = (v, a, b) => Math.max(0, Math.min(1, (v - a) / (b - a)))
const rand = (a, b) => a + Math.random() * (b - a)
const pick = (arr) => arr[(Math.random() * arr.length) | 0]
const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y)

function shuffle(a) {
  const r = a.slice()
  for (let i = r.length - 1; i > 0; i--) {
    const j = (Math.random() * (i + 1)) | 0
    ;[r[i], r[j]] = [r[j], r[i]]
  }
  return r
}

function weightPick(items) {
  let total = 0
  for (const it of items) total += it.w
  let r = Math.random() * total
  for (const it of items) { r -= it.w; if (r <= 0) return it }
  return items[items.length - 1]
}

export class Game {
  constructor(canvas, input, renderer) {
    this.canvas = canvas
    this.input = input
    this.renderer = renderer
    this.state = 'title'
    this.ui = {}
    for (const id of ['hud', 'hpFill', 'hpText', 'xpFill', 'lvlBadge', 'clock', 'objective', 'killCount',
      'bossWrap', 'bossTitle', 'bossFill', 'bossHpText', 'spellRail', 'dashBtn', 'dashCd', 'hintLine',
      'waveBanner', 'titleScreen', 'startBtn', 'levelup', 'newLevel', 'cards', 'pauseScreen', 'resumeBtn',
      'quitBtn', 'pauseStats', 'loadout', 'endScreen', 'endTitle', 'endLine', 'endStats', 'endSpells',
      'retryBtn', 'bestLine', 'muteBtn', 'pauseBtn', 'endInner']) {
      this.ui[id] = document.getElementById(id)
    }
    this.endInner = document.querySelector('.end-inner')
    this.muted = false
    this.best = this.loadBest()
    this.hudTimer = 0
    this.bannerTimer = 0
    this.hintTimer = 0
    this.chipEls = {}
    this.ambientTime = 0
    this.resetWorld()
    this.state = 'title'
    this.bindUI()
  }

  // ── setup ────────────────────────────────────────────────────────────────
  bindUI() {
    this.ui.startBtn.addEventListener('click', () => { sfx('click'); this.beginRun() })
    this.ui.retryBtn.addEventListener('click', () => { sfx('click'); this.beginRun() })
    this.ui.pauseBtn.addEventListener('click', () => this.togglePause())
    this.ui.resumeBtn.addEventListener('click', () => this.togglePause(false))
    this.ui.quitBtn.addEventListener('click', () => { sfx('click'); this.quitToTitle() })
    this.ui.muteBtn.addEventListener('click', () => {
      this.muted = !this.muted
      import('./audio.js').then((a) => a.setMuted(this.muted))
      this.ui.muteBtn.classList.toggle('muted', this.muted)
    })
    this.ui.dashBtn.addEventListener('pointerdown', (e) => {
      e.preventDefault()
      this.input.queueDash()
    })
    this.ui.cards.addEventListener('click', (e) => {
      const card = e.target.closest('.card')
      if (!card) return
      this.chooseCard(Number(card.dataset.index))
    })
    window.addEventListener('keydown', (e) => this.onKey(e))
  }

  onKey(e) {
    if (e.repeat) return
    if (this.state === 'levelup') {
      if (e.code === 'Digit1' || e.code === 'Numpad1') this.chooseCard(0)
      else if (e.code === 'Digit2' || e.code === 'Numpad2') this.chooseCard(1)
      else if (e.code === 'Digit3' || e.code === 'Numpad3') this.chooseCard(2)
      return
    }
    if (e.code === 'Escape' || e.code === 'KeyP') {
      e.preventDefault()
      if (this.state === 'playing') this.togglePause(true)
      else if (this.state === 'paused') this.togglePause(false)
    }
    if ((this.state === 'dead' || this.state === 'victory') && (e.code === 'Enter' || e.code === 'KeyR')) {
      this.beginRun()
    }
  }

  loadBest() {
    try {
      const v = JSON.parse(localStorage.getItem('emberwitch.best') || 'null')
      if (v && typeof v.time === 'number') return v
    } catch {}
    return { time: 0, kills: 0, level: 0 }
  }

  saveBest() {
    const b = this.best
    let changed = false
    if (this.time > b.time) { b.time = this.time; changed = true }
    if (this.kills > b.kills) { b.kills = this.kills; changed = true }
    if (this.level > b.level) { b.level = this.level; changed = true }
    if (changed) { try { localStorage.setItem('emberwitch.best', JSON.stringify(b)) } catch {} }
  }

  resetWorld() {
    this.time = 0
    this.level = 1
    this.xp = 0
    this.xpNext = this.xpNeeded(1)
    this.pendingLevels = 0
    this.kills = 0
    this.score = 0
    this.bossesSlain = 0
    this.player = {
      x: WORLD.w / 2, y: WORLD.h / 2 + 60,
      vx: 0, vy: 0, r: 15,
      hp: 100, maxHp: 100,
      facing: -Math.PI / 2, aim: -Math.PI / 2,
      attackTimer: 0, attackCd: 0.86,
      invuln: 0, hurtTimer: 0,
      dashTimer: 0, dashCd: 0, dashDir: { x: 0, y: -1 },
      shield: 0, shieldMax: 0, regenTick: 0,
      trailTimer: 0,
    }
    this.camera = { x: this.player.x, y: this.player.y }
    this.enemies = []
    this.projectiles = []
    this.pickups = []
    this.particles = []
    this.effects = []
    this.zones = []
    this.texts = []
    this.strikes = []
    this.spells = { ember: 1 }
    this.boons = {}
    this.cds = {}
    this.spawnTimer = 1.2
    this.wave = 0
    this.shake = 0
    this.hurtFlash = 0
    this.bossRef = null
    this.bossSpawned = { warden: false, king: false }
    this.bossKilled = { warden: false, king: false }
    this.victoryTimer = -1
    this.familiarTick = 0
    this.lastFired = 0
    this.killsAtStart = 0
    this.spawnGrace = 0
    this.slowmo = 0
    this.chipEls = {}
  }

  xpNeeded(level) {
    return Math.round(6 + level * 3 + Math.pow(level, 1.45) * 1.2)
  }

  beginRun() {
    this.resetWorld()
    this.ui.titleScreen.classList.add('hidden')
    this.ui.endScreen.classList.add('hidden')
    this.ui.pauseScreen.classList.add('hidden')
    this.ui.levelup.classList.add('hidden')
    this.ui.hud.classList.remove('hidden')
    this.ui.bossWrap.classList.add('hidden')
    this.state = 'playing'
    this.syncHUD(true)
    this.buildRail()
    // a few welcoming beasts
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * TAU + 0.4
      this.spawnEnemy('slime', this.player.x + Math.cos(a) * 260, this.player.y + Math.sin(a) * 260, { quiet: true })
    }
    this.showBanner('THE GROVE STIRS')
    this.showHint('Left thumb moves · right thumb aims · dash through danger', 9)
    this.hudTimer = 0
    sfx('boss')
  }

  quitToTitle() {
    this.state = 'title'
    this.ui.hud.classList.add('hidden')
    this.ui.pauseScreen.classList.add('hidden')
    this.ui.bossWrap.classList.add('hidden')
    this.ui.endScreen.classList.add('hidden')
    this.ui.titleScreen.classList.remove('hidden')
    this.resetWorld()
  }

  // ── UI bits ──────────────────────────────────────────────────────────────
  spellCooldown(id, rank) {
    switch (id) {
      case 'ember': return (0.86 - 0.07 * (rank - 1))
      case 'frost': return 3.6 - 0.2 * (rank - 1)
      case 'chain': return 4.4 - 0.25 * (rank - 1)
      case 'bramble': return 5.2
      case 'hex': return 5.6
      case 'meteor': return 8.5
      case 'siphon': return 6.4
      case 'ward': return 9.0
      default: return 6
    }
  }

  buildRail(newId = null) {
    const rail = this.ui.spellRail
    rail.innerHTML = ''
    this.chipEls = {}
    const ids = ['ember', ...SPELL_ORDER.filter((id) => this.spells[id])]
    for (const id of ids) {
      const sp = SPELLS[id]
      const rank = this.spells[id] || 1
      const el = document.createElement('div')
      el.className = 'spell-chip' + (id === newId ? ' new' : '')
      el.style.setProperty('--c', sp.color)
      el.title = `${sp.name} · Rank ${ROMAN[rank]}`
      el.innerHTML = `${sp.icon}<span class="rk">${ROMAN[rank]}</span><i class="cd"></i>`
      rail.appendChild(el)
      const cd = el.querySelector('.cd')
      cd.style.transformOrigin = 'top'
      cd.style.transform = 'scaleY(0)'
      cd.style.opacity = '0'
      this.chipEls[id] = { el, cd, rank }
    }
  }

  refreshRail() { this.buildRail() }

  showBanner(text) {
    const el = this.ui.waveBanner
    el.classList.remove('show')
    void el.offsetWidth
    el.textContent = text
    el.classList.add('show')
    this.bannerTimer = 2.6
  }

  showHint(text, secs = 7) {
    const el = this.ui.hintLine
    el.textContent = text
    el.classList.add('show')
    this.hintTimer = secs
  }

  togglePause(force) {
    if (this.state === 'playing' && force !== false) {
      this.state = 'paused'
      this.ui.pauseScreen.classList.remove('hidden')
      this.fillPause()
      sfx('click')
    } else if (this.state === 'paused' && force !== true) {
      this.state = 'playing'
      this.ui.pauseScreen.classList.add('hidden')
      this.showHint('The grove waits for no witch', 2)
      sfx('click')
    }
  }

  fillPause() {
    this.ui.pauseStats.innerHTML = `
      <div><span>Time</span><b>${this.fmtTime(this.time)}</b></div>
      <div><span>Level</span><b>${this.level}</b></div>
      <div><span>Slain</span><b>${this.kills}</b></div>
      <div><span>Spells</span><b>${Object.keys(this.spells).length}</b></div>`
    this.fillLoadout(this.ui.loadout)
  }

  fillLoadout(el) {
    el.innerHTML = ''
    for (const id of ['ember', ...SPELL_ORDER.filter((id) => this.spells[id])]) {
      const sp = SPELLS[id]
      const rank = this.spells[id]
      const d = document.createElement('div')
      d.className = 'lo'
      d.style.setProperty('--c', sp.color)
      d.innerHTML = `${sp.icon}<span>${sp.name}</span><b>${ROMAN[rank]}</b>`
      el.appendChild(d)
    }
    for (const id of Object.keys(this.boons)) {
      const b = BOONS[id]
      const d = document.createElement('div')
      d.className = 'lo'
      d.style.setProperty('--c', b.color)
      d.innerHTML = `${b.icon}<span>${b.name}</span><b>${ROMAN[this.boons[id]]}</b>`
      el.appendChild(d)
    }
  }

  fmtTime(t) {
    const s = Math.max(0, Math.floor(t))
    return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`
  }

  // ── stats ────────────────────────────────────────────────────────────────
  get maxHp() { return 100 + (this.boons.vitality || 0) * 22 + (this.level - 1) * 2 }
  get moveSpeed() { return 158 * (1 + (this.boons.swift || 0) * 0.07) }
  get castSpeed() { return 1 + (this.boons.focus || 0) * 0.10 }
  get damageMult() { return 1 + (this.boons.might || 0) * 0.12 }
  get xpMult() { return 1 + (this.boons.fortune || 0) * 0.12 }
  get magnetRadius() { return 65 + (this.boons.magnet || 0) * 55 }
  get regen() { return 0.12 + (this.boons.regen || 0) * 0.4 }

  spellDmg(base) { return base * this.damageMult }

  // ── main update ──────────────────────────────────────────────────────────
  update(dt) {
    if (this.state === 'playing') {
      this.updateRun(dt)
    } else {
      // keep the frozen scene's timers gentle
      this.shake *= Math.pow(0.001, dt)
      this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2)
      if (this.state === 'dead' || this.state === 'victory') {
        this.stepParticles(dt)
        this.stepTexts(dt)
      }
    }
    this.updateCooldownUI()
  }

  updateRun(dt) {
    this.time += dt
    this.spawnGrace = Math.max(0, this.spawnGrace - dt)
    this.shake *= Math.pow(0.0015, dt)
    this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2.6)
    if (this.hintTimer > 0) {
      this.hintTimer -= dt
      if (this.hintTimer <= 0) this.ui.hintLine.classList.remove('show')
    }
    if (this.bannerTimer > 0) this.bannerTimer -= dt

    this.updateBossTriggers()
    this.updatePlayer(dt)
    this.updateSpells(dt)
    this.updateEnemies(dt)
    this.updateZones(dt)
    this.updateProjectiles(dt)
    this.updateStrikes(dt)
    this.updatePickups(dt)
    this.stepParticles(dt)
    this.stepEffects(dt)
    this.stepTexts(dt)
    this.updateSpawner(dt)
    this.updateCamera(dt)
    this.updateVictory(dt)

    this.hudTimer -= dt
    if (this.hudTimer <= 0) { this.syncHUD(); this.hudTimer = 0.09 }
  }

  updateBossTriggers() {
    if (!this.bossSpawned.warden && this.time >= 58) {
      this.bossSpawned.warden = true
      this.spawnBoss('warden')
    }
    if (!this.bossSpawned.king && this.bossKilled.warden && this.time >= 150) {
      this.bossSpawned.king = true
      this.spawnBoss('king')
    }
  }

  spawnBoss(kind) {
    const def = BOSSES[kind]
    const a = rand(0, TAU)
    let x = clamp(this.player.x + Math.cos(a) * 340, 120, WORLD.w - 120)
    let y = clamp(this.player.y + Math.sin(a) * 340, 120, WORLD.h - 120)
    const scale = 1 + this.time * 0.0035
    const e = {
      type: 'boss', bossKind: kind, isBoss: true, def,
      x, y, hp: def.hp * scale, maxHp: def.hp * scale,
      speed: def.speed, radius: def.radius, damage: def.damage * (1 + this.time * 0.005),
      xp: def.xp, score: def.score, color: def.color, seed: Math.random(),
      hitCd: 0, flash: 0, slow: 0, atkCd: 2.4, windup: 0, windupMax: 0,
      phase: 0, elite: false, dead: false, bossColor: def.color, spawnAnim: 1.2,
    }
    this.enemies.push(e)
    this.bossRef = e
    this.showBanner(kind === 'warden' ? 'THE BRIAR WARDEN AWAKENS' : 'THE HOLLOW KING RISES')
    this.ui.bossTitle.textContent = def.name.toUpperCase()
    this.ui.bossWrap.classList.remove('hidden')
    this.effects.push({ type: 'ring', x, y, r: 130, r0: 10, life: 0.9, maxLife: 0.9, color: def.color, width: 5, flat: true, layer: 'top' })
    this.burst(x, y, def.color, 30, 3.2)
    this.shake = 18
    sfx('boss')
  }

  // ── player ───────────────────────────────────────────────────────────────
  updatePlayer(dt) {
    const p = this.player
    const inp = this.input
    p.maxHp = this.maxHp
    p.attackCd = this.spellCooldown('ember', this.spells.ember) / this.castSpeed

    p.invuln = Math.max(0, p.invuln - dt)
    p.hurtTimer = Math.max(0, p.hurtTimer - dt)
    p.attackTimer -= dt
    p.dashCd = Math.max(0, p.dashCd - dt)

    // movement
    const mv = inp.moveVec
    let spd = this.moveSpeed
    if (p.dashTimer > 0) {
      p.dashTimer -= dt
      p.x += p.dashDir.x * 520 * dt
      p.y += p.dashDir.y * 520 * dt
      p.trailTimer -= dt
      if (p.trailTimer <= 0) {
        p.trailTimer = 0.028
        this.particles.push({ x: p.x + rand(-4, 4), y: p.y + rand(-8, 6), vx: rand(-10, 10), vy: rand(-10, 10), life: 0.32, maxLife: 0.32, size: rand(4, 8), color: '#c9a6ff', glow: true, shape: 'circle', drag: 0.9 })
      }
    } else {
      p.vx = mv.x * spd * mv.mag
      p.vy = mv.y * spd * mv.mag
      p.x += p.vx * dt
      p.y += p.vy * dt
      if (mv.mag > 0.05) this.ambientTime += dt
    }
    p.x = clamp(p.x, 70, WORLD.w - 70)
    p.y = clamp(p.y, 70, WORLD.h - 70)

    // dash
    if (inp.consumeDash() && p.dashCd <= 0 && p.dashTimer <= 0) {
      const dir = mv.mag > 0.1 ? mv : { x: Math.cos(p.aim), y: Math.sin(p.aim) }
      p.dashDir = { x: dir.x, y: dir.y }
      p.dashTimer = 0.17
      p.dashCd = 1.5
      p.invuln = Math.max(p.invuln, 0.34)
      this.shake = Math.max(this.shake, 3)
      this.particles.push({ x: p.x, y: p.y, vx: 0, vy: 0, life: 0.3, maxLife: 0.3, size: 10, color: '#c9a6ff', glow: true, shape: 'circle', drag: 0.85 })
      sfx('dash')
    }

    // aim: right stick > mouse > nearest > movement
    let aimTarget = null
    const target = this.nearestEnemy(p.x, p.y, 640)
    const av = inp.aimVec
    if (av.active) {
      p.aim = Math.atan2(av.y, av.x)
      aimTarget = target
    } else if (!inp.usedTouch && inp.mouse.inside) {
      const psx = this.renderer.w / 2 + (p.x - this.camera.x)
      const psy = this.renderer.h / 2 + (p.y - this.camera.y - 10)
      p.aim = Math.atan2(inp.mouse.y - psy, inp.mouse.x - psx)
      aimTarget = target
    } else if (target && dist(p, target) < 640) {
      p.aim = Math.atan2(target.y - p.y, target.x - p.x)
      aimTarget = target
    } else if (mv.mag > 0.1) {
      p.aim = Math.atan2(mv.y, mv.x)
    }
    p.facing = p.aim

    // auto-fire ember
    const wantFire = target || av.active || (!inp.usedTouch && inp.mouse.inside && inp.mouse.down)
    if (p.attackTimer <= 0 && wantFire) {
      this.castEmber(av.active ? p.aim : (target ? Math.atan2(target.y - p.y, target.x - p.x) : p.aim))
      p.attackTimer = p.attackCd
    }

    // dash invulnerability & regen
    if (p.invuln <= 0) {
      p.hp = Math.min(p.maxHp, p.hp + this.regen * dt)
    }
    if (p.hp <= 0) this.die()

    // mouse firing
    if (!inp.usedTouch && inp.mouse.down && p.attackTimer > 0.85) p.attackTimer = p.attackCd * 0.5
  }

  nearestEnemy(x, y, range) {
    let best = null, bd = range * range
    for (const e of this.enemies) {
      if (e.dead) continue
      const d = (e.x - x) ** 2 + (e.y - y) ** 2
      if (d < bd) { bd = d; best = e }
    }
    return best
  }

  enemiesIn(x, y, r) {
    const out = []
    for (const e of this.enemies) {
      if (e.dead) continue
      if (Math.hypot(e.x - x, e.y - y) <= r + e.radius) out.push(e)
    }
    return out
  }

  // ── spells ───────────────────────────────────────────────────────────────
  castEmber(angle) {
    const p = this.player
    const rank = this.spells.ember
    const count = 1 + (rank >= 3 ? 1 : 0) + (rank >= 5 ? 1 : 0)
    const baseDmg = this.spellDmg(10 + 4 * (rank - 1))
    const mx = p.x + Math.cos(angle) * 20
    const my = p.y - 8 + Math.sin(angle) * 12
    for (let i = 0; i < count; i++) {
      const off = count === 1 ? 0 : (i - (count - 1) / 2) * 0.11
      const a = angle + off
      this.projectiles.push({
        kind: 'ember', x: mx, y: my, vx: Math.cos(a) * 610, vy: Math.sin(a) * 610,
        r: 7.5, dmg: baseDmg, life: 1.05, maxLife: 1.05, color: '#ff9a4d', pierce: rank >= 4 ? 1 : 0,
        hit: [], angle: a,
      })
    }
    for (let i = 0; i < 3; i++) {
      this.particles.push({
        x: mx, y: my, vx: Math.cos(angle) * rand(20, 90) + rand(-25, 25), vy: Math.sin(angle) * rand(20, 90) + rand(-25, 25),
        life: rand(0.16, 0.32), maxLife: 0.32, size: rand(1.2, 2.6), color: '#ffb46b', glow: true, shape: 'spark', drag: 0.92,
      })
    }
    sfx('shoot')
  }

  updateSpells(dt) {
    const p = this.player
    for (const id of Object.keys(this.spells)) {
      if (id === 'ember') continue
      if (id === 'familiar') continue
      this.cds[id] = (this.cds[id] || 0) - dt
      if (this.cds[id] > 0) continue
      const rank = this.spells[id]
      let cast = false
      if (id === 'frost') cast = this.castFrost(rank)
      else if (id === 'chain') cast = this.castChain(rank)
      else if (id === 'bramble') cast = this.castBramble(rank)
      else if (id === 'hex') cast = this.castHex(rank)
      else if (id === 'meteor') cast = this.castMeteor(rank)
      else if (id === 'siphon') cast = this.castSiphon(rank)
      else if (id === 'ward') cast = this.castWard(rank)
      if (cast) this.cds[id] = this.spellCooldown(id, rank) / this.castSpeed
    }
    // familiar contact damage
    if (this.spells.familiar) {
      const rank = this.spells.familiar
      const count = rank >= 4 ? 2 : 1
      this.familiarTick -= dt
      if (this.familiarTick <= 0) {
        this.familiarTick = 0.34
        for (let i = 0; i < count; i++) {
          const a = this.time * 1.5 + i * Math.PI
          const fx = p.x + Math.cos(a) * 46
          const fy = p.y - 6 + Math.sin(a) * 22
          const hits = this.enemiesIn(fx, fy, 15)
          if (hits.length) {
            for (const e of hits.slice(0, 2)) this.damageEnemy(e, this.spellDmg(6 + 3 * (rank - 1)), { silent: true, color: '#c9a6ff' })
            this.burst(fx, fy, '#c9a6ff', 3, 1.6)
            sfx('hit')
          }
        }
      }
    }
  }

  castFrost(rank) {
    const p = this.player
    const r = 108 + 14 * (rank - 1)
    const dmg = this.spellDmg(9 + 5 * (rank - 1))
    this.effects.push({ type: 'nova', x: p.x, y: p.y, r, life: 0.55, maxLife: 0.55, layer: 'top' })
    for (const e of this.enemiesIn(p.x, p.y, r)) {
      this.damageEnemy(e, dmg, { color: '#8fe1ff' })
      e.slow = Math.max(e.slow, 2)
    }
    for (let i = 0; i < 18; i++) {
      const a = rand(0, TAU), d = rand(20, r)
      this.particles.push({
        x: p.x + Math.cos(a) * d, y: p.y + Math.sin(a) * d,
        vx: Math.cos(a) * rand(30, 130), vy: Math.sin(a) * rand(30, 130),
        life: rand(0.3, 0.65), maxLife: 0.65, size: rand(1.5, 3.4), color: '#bdefff', glow: true, shape: 'spark', drag: 0.9,
      })
    }
    this.shake = Math.max(this.shake, 4)
    sfx('nova')
    return true
  }

  castChain(rank) {
    const p = this.player
    const first = this.nearestEnemy(p.x, p.y, 560)
    if (!first) return false
    const jumps = 2 + rank
    const dmg = this.spellDmg(13 + 5 * (rank - 1))
    const hit = new Set()
    let cur = first
    const pts = [{ x: p.x, y: p.y - 8 }, { x: first.x, y: first.y }]
    for (let i = 0; i < jumps; i++) {
      if (!cur || cur.dead) break
      hit.add(cur)
      this.damageEnemy(cur, dmg, { color: '#cbb5ff', chain: true })
      const next = this.enemies
        .filter((e) => !e.dead && !hit.has(e))
        .map((e) => ({ e, d: Math.hypot(e.x - cur.x, e.y - cur.y) }))
        .filter((o) => o.d < 230)
        .sort((a, b) => a.d - b.d)[0]
      if (next) { pts.push({ x: next.e.x, y: next.e.y }); }
      cur = next ? next.e : null
    }
    // jittered lightning
    const path = []
    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i], b = pts[i + 1]
      path.push({ x: a.x, y: a.y })
      const segs = 4
      for (let s = 1; s < segs; s++) {
        const t = s / segs
        path.push({ x: lerp(a.x, b.x, t) + rand(-7, 7), y: lerp(a.y, b.y, t) + rand(-7, 7) })
      }
    }
    path.push(pts[pts.length - 1])
    this.effects.push({ type: 'lightning', pts: path, color: '#b9a3ff', life: 0.28, maxLife: 0.28, layer: 'top' })
    sfx('chain')
    return true
  }

  castBramble(rank) {
    const p = this.player
    const t = this.nearestEnemy(p.x, p.y, 520)
    if (!t) return false
    const r = 68 + 8 * rank
    this.zones.push({
      type: 'bramble', x: t.x, y: t.y, r, life: 4.2, maxLife: 4.2, tick: 0, tickRate: 0.5,
      dmg: this.spellDmg(4 + 2 * (rank - 1)), seed: Math.random(), slow: true,
    })
    this.effects.push({ type: 'ring', x: t.x, y: t.y, r: r + 8, r0: 10, life: 0.5, maxLife: 0.5, color: '#9be6a8', width: 3, flat: true, layer: 'top' })
    this.burst(t.x, t.y, '#9be6a8', 12, 2.4)
    sfx('lob')
    return true
  }

  castHex(rank) {
    const p = this.player
    const t = this.nearestEnemy(p.x, p.y, 560)
    if (!t) return false
    const mx = p.x, my = p.y - 16
    this.projectiles.push({
      kind: 'vial', x: mx, y: my, sx: mx, sy: my, tx: t.x, ty: t.y,
      t: 0, dur: 0.55, r: 4, life: 1.4, maxLife: 1.4, color: '#b8f27a', rank,
      dmg: this.spellDmg(3 + 2 * (rank - 1)), vx: 0, vy: 0,
    })
    sfx('lob')
    return true
  }

  castMeteor(rank) {
    const p = this.player
    const t = this.nearestEnemy(p.x, p.y, 560)
    if (!t) return false
    const r = 92 + 6 * rank
    const dmg = this.spellDmg(46 + 16 * (rank - 1))
    this.effects.push({ type: 'telegraph', x: t.x, y: t.y, r, life: 0.95, maxLife: 0.95, color: '#ff9a4d', extra: 'meteor', layer: 'ground' })
    this.strikes.push({ type: 'meteor', x: t.x, y: t.y, r, dmg, delay: 0.95, delayMax: 0.95, rank })
    sfx('lob')
    return true
  }

  castSiphon(rank) {
    const p = this.player
    const t = this.nearestEnemy(p.x, p.y, 500)
    if (!t) return false
    const dmg = this.spellDmg(34 + 14 * (rank - 1))
    const healed = Math.min(this.maxHp - p.hp, dmg * 0.55)
    this.effects.push({ type: 'beam', x1: p.x, y1: p.y - 6, x2: t.x, y2: t.y, color: '#ff7d9e', life: 0.42, maxLife: 0.42, layer: 'top' })
    this.damageEnemy(t, dmg, { color: '#ff9db4' })
    if (healed > 0) {
      p.hp += healed
      this.addText(p.x, p.y - 30, `+${Math.round(healed)}`, '#ffb3c4', 12)
      this.particles.push({ x: t.x, y: t.y, vx: 0, vy: 0, life: 0.4, maxLife: 0.4, size: 8, color: '#ff7d9e', glow: true, shape: 'circle', drag: 0.9 })
    }
    this.burst(t.x, t.y, '#ff7d9e', 12, 2.6)
    sfx('siphon')
    return true
  }

  castWard(rank) {
    const p = this.player
    if (p.shield > 1 && p.shieldMax > 0) return false
    p.shieldMax = 24 + 12 * (rank - 1)
    p.shield = p.shieldMax
    this.effects.push({ type: 'ring', x: p.x, y: p.y - 6, r: 44, r0: 10, life: 0.5, maxLife: 0.5, color: '#a8c8ff', width: 2, layer: 'top' })
    this.burst(p.x, p.y - 6, '#a8c8ff', 10, 2)
    sfx('ward')
    return true
  }

  // ── enemies ──────────────────────────────────────────────────────────────
  spawnEnemy(type, x, y, opts = {}) {
    const def = ENEMIES[type]
    const elite = !!opts.elite
    const hpScale = 1 + this.time * 0.032
    const dmgScale = 1 + this.time * 0.008
    const e = {
      type, def, x, y,
      hp: def.hp * hpScale * (elite ? 2.4 : 1),
      maxHp: def.hp * hpScale * (elite ? 2.4 : 1),
      speed: def.speed * (1 + Math.min(0.28, this.time * 0.0012)) * (elite ? 0.92 : 1),
      radius: def.radius * (elite ? 1.18 : 1),
      damage: def.damage * dmgScale * (elite ? 1.35 : 1),
      xp: def.xp * (elite ? 3 : 1),
      score: def.score * (elite ? 3 : 1),
      color: def.color, seed: Math.random(),
      hitCd: 0, flash: 0, slow: 0, atkCd: rand(1.2, 2.6), windup: 0, windupMax: 0,
      chargeCd: rand(2, 4), charging: 0, chargeDir: { x: 0, y: 0 },
      elite, dead: false, wob: rand(0, TAU),
    }
    this.enemies.push(e)
    if (!opts.quiet) {
      this.effects.push({ type: 'spawnRing', x, y, r: 34, life: 0.42, maxLife: 0.42, color: elite ? '#ffb15e' : '#9a6ad6', layer: 'top' })
    }
    return e
  }

  updateEnemies(dt) {
    const p = this.player
    for (const e of this.enemies) {
      if (e.dead) continue
      e.flash = Math.max(0, e.flash - dt)
      e.slow = Math.max(0, e.slow - dt)
      e.hitCd = Math.max(0, e.hitCd - dt)
      if (e.spawnAnim) e.spawnAnim = Math.max(0, e.spawnAnim - dt)
      const dx = p.x - e.x, dy = p.y - e.y
      const d = Math.hypot(dx, dy) || 1
      const nx = dx / d, ny = dy / d
      const slowFactor = e.slow > 0 ? 0.52 : 1

      if (e.isBoss) {
        this.updateBoss(e, dt, nx, ny, d, slowFactor)
      } else if (e.def.ranged) {
        // mournful caster keeps its distance
        let spd = e.speed * slowFactor
        if (d < 200) spd *= -0.7
        else if (d < 300) spd *= 0.1
        const strafe = Math.sin(this.time * 1.4 + e.seed * 7) * 0.6
        e.x += (nx * spd + -ny * spd * strafe) * dt
        e.y += (ny * spd + nx * spd * strafe) * dt
        e.atkCd -= dt
        if (e.atkCd <= 0 && d < 470) {
          e.atkCd = rand(2.3, 3.0)
          const a = Math.atan2(dy, dx)
          this.enemyShot(e.x, e.y, a, 175, 8 * (1 + this.time * 0.004), '#8fd7ff', 6.5)
          sfx('lob')
        }
      } else if (e.def.charger) {
        if (e.charging > 0) {
          e.charging -= dt
          e.x += e.chargeDir.x * 430 * dt
          e.y += e.chargeDir.y * 430 * dt
          e.trailTimer = (e.trailTimer || 0) - dt
          if (e.trailTimer <= 0) {
            e.trailTimer = 0.03
            this.particles.push({ x: e.x, y: e.y, vx: rand(-10, 10), vy: rand(-10, 10), life: 0.3, maxLife: 0.3, size: rand(2, 4), color: '#ff8a5b', glow: true, shape: 'circle', drag: 0.9 })
          }
        } else if (e.windup > 0) {
          e.windup -= dt
          if (e.windup <= 0) {
            e.charging = 0.3
            const a = Math.atan2(p.y - e.y, p.x - e.x)
            e.chargeDir = { x: Math.cos(a), y: Math.sin(a) }
            sfx('dash')
          }
        } else {
          e.x += nx * e.speed * slowFactor * dt
          e.y += ny * e.speed * slowFactor * dt
          e.chargeCd -= dt
          if (e.chargeCd <= 0 && d < 300) {
            e.chargeCd = rand(3, 4.5)
            e.windup = 0.5
            e.windupMax = 0.5
          }
        }
      } else if (e.type === 'skeleton' || e.type === 'hound') {
        if (e.windup > 0) {
          e.windup -= dt
          if (e.windup <= 0) {
            if (d < e.radius + 55) {
              this.effects.push({ type: 'ring', x: e.x, y: e.y, r: 58, r0: 10, life: 0.3, maxLife: 0.3, color: '#ff8a8a', width: 2, flat: true, layer: 'top' })
              this.damagePlayer(e.damage * 1.25, e)
            }
            this.burst(e.x + nx * 20, e.y + ny * 20, '#d8cfb4', 5, 2)
          }
        } else {
          e.x += nx * e.speed * slowFactor * dt
          e.y += ny * e.speed * slowFactor * dt
          if (d < e.radius + 34) {
            e.windup = 0.55
            e.windupMax = 0.55
          }
        }
      } else {
        // slime, bat — simple chase; bats weave
        let vx = nx * e.speed * slowFactor, vy = ny * e.speed * slowFactor
        if (e.type === 'bat') {
          const w = Math.sin(this.time * 4 + e.seed * 8) * 0.55
          const tx = vx - ny * vy * w, ty = vy + nx * vx * w
          vx = tx; vy = ty
        }
        e.x += vx * dt
        e.y += vy * dt
      }

      // soft separation
      e.x = clamp(e.x, 50, WORLD.w - 50)
      e.y = clamp(e.y, 50, WORLD.h - 50)

      // contact
      if (d < e.radius + p.r + (e.charging > 0 ? 4 : 0)) {
        if (e.hitCd <= 0) {
          e.hitCd = e.isBoss ? 0.9 : 0.7
          this.damagePlayer(e.damage * (e.charging > 0 ? 1.3 : 1), e)
          // knock player back
          p.x += nx * 9
          p.y += ny * 9
        }
      }
    }

    // separation pass
    const arr = this.enemies
    for (let i = 0; i < arr.length; i++) {
      const a = arr[i]
      if (a.dead) continue
      for (let j = i + 1; j < arr.length; j++) {
        const b = arr[j]
        if (b.dead) continue
        const dx = b.x - a.x, dy = b.y - a.y
        const min = a.radius + b.radius
        const d2 = dx * dx + dy * dy
        if (d2 > 0.01 && d2 < min * min) {
          const d = Math.sqrt(d2)
          const push = ((min - d) / d) * 0.24
          const wa = a.isBoss ? 0.05 : 1, wb = b.isBoss ? 0.05 : 1
          a.x -= dx * push * wa; a.y -= dy * push * wa
          b.x += dx * push * wb; b.y += dy * push * wb
        }
      }
    }

    this.enemies = this.enemies.filter((e) => !e.dead)
    if (this.bossRef && this.bossRef.dead) {
      this.bossRef = null
      this.ui.bossWrap.classList.add('hidden')
    }
  }

  enemyShot(x, y, a, speed, dmg, color, r) {
    this.projectiles.push({
      kind: 'enemy', x, y, vx: Math.cos(a) * speed, vy: Math.sin(a) * speed,
      r, dmg, life: 3.2, maxLife: 3.2, color, pierce: 0,
    })
  }

  updateBoss(e, dt, nx, ny, d, slowFactor) {
    if (e.windup > 0) {
      e.windup -= dt
      if (e.windup <= 0) this.bossSlam(e)
      return
    }
    // slow pursuit
    const spd = e.speed * slowFactor * (e.bossKind === 'king' ? 1.05 : 1)
    e.x += nx * spd * dt
    e.y += ny * spd * dt
    e.atkCd -= dt
    if (e.atkCd > 0) return

    if (e.bossKind === 'warden') {
      e.atkCd = 3.1
      const mode = e.phase++ % 3
      if (mode === 0) {
        const n = 12
        for (let i = 0; i < n; i++) {
          const a = (i / n) * TAU + this.time * 0.3
          this.enemyShot(e.x, e.y, a, 165, e.damage * 0.55, '#a4ff8a', 7)
        }
        this.effects.push({ type: 'ring', x: e.x, y: e.y, r: 50, r0: 5, life: 0.35, maxLife: 0.35, color: '#a4ff8a', width: 2, flat: true, layer: 'top' })
        sfx('nova')
      } else if (mode === 1) {
        this.summonAdds(e, 'slime', 3)
      } else {
        e.windup = 0.85
        e.windupMax = 0.85
        e.slamR = 105
      }
    } else {
      e.atkCd = 2.8
      const mode = e.phase++ % 4
      if (mode === 0) {
        const n = 20
        for (let i = 0; i < n; i++) {
          const a = (i / n) * TAU
          this.enemyShot(e.x, e.y, a, 155, e.damage * 0.5, '#c79aff', 7)
        }
        sfx('nova')
      } else if (mode === 1) {
        this.summonAdds(e, 'wraith', 2)
      } else if (mode === 2) {
        e.windup = 0.8
        e.windupMax = 0.8
        e.slamR = 125
      } else {
        // blink and blast
        const a = rand(0, TAU)
        const nx2 = clamp(this.player.x + Math.cos(a) * 170, 80, WORLD.w - 80)
        const ny2 = clamp(this.player.y + Math.sin(a) * 170, 80, WORLD.h - 80)
        this.effects.push({ type: 'burst', x: e.x, y: e.y, r: 60, color: '#c79aff', life: 0.5, maxLife: 0.5, layer: 'top' })
        this.burst(e.x, e.y, '#c79aff', 18, 3)
        e.x = nx2; e.y = ny2
        this.effects.push({ type: 'burst', x: e.x, y: e.y, r: 60, color: '#c79aff', life: 0.5, maxLife: 0.5, layer: 'top' })
        this.burst(e.x, e.y, '#f0e0ff', 18, 3)
        sfx('dash')
      }
    }
  }

  bossSlam(e) {
    const r = e.slamR || 100
    const p = this.player
    const d = Math.hypot(p.x - e.x, p.y - e.y)
    this.effects.push({ type: 'ring', x: e.x, y: e.y, r: r + 18, r0: 8, life: 0.55, maxLife: 0.55, color: e.bossKind === 'king' ? '#c79aff' : '#a4ff8a', width: 6, flat: true, layer: 'top' })
    this.burst(e.x, e.y, e.bossKind === 'king' ? '#c79aff' : '#a4ff8a', 24, 4)
    if (d < r + p.r) this.damagePlayer(e.damage * 1.4, e)
    this.shake = Math.max(this.shake, 12)
    // boss lunges toward player on slam
    const a = Math.atan2(p.y - e.y, p.x - e.x)
    e.x += Math.cos(a) * 60
    e.y += Math.sin(a) * 60
    sfx('meteor')
  }

  summonAdds(boss, type, n) {
    if (this.enemies.filter((e) => !e.isBoss).length > 26) return
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU)
      const x = clamp(boss.x + Math.cos(a) * rand(50, 100), 60, WORLD.w - 60)
      const y = clamp(boss.y + Math.sin(a) * rand(50, 100), 60, WORLD.h - 60)
      this.spawnEnemy(type, x, y)
      this.burst(x, y, '#9a6ad6', 6, 2)
    }
  }

  updateSpawner(dt) {
    if (this.spawnGrace > 0) return
    const normalCount = this.enemies.filter((e) => !e.isBoss).length
    const cap = 18 + Math.min(32, this.time * 0.16)
    const target = Math.min(cap, 6 + this.time * 0.22)
    this.spawnTimer -= dt
    if (this.spawnTimer <= 0 && normalCount < target) {
      const batch = this.time > 100 ? 2 : 1
      for (let i = 0; i < batch; i++) {
        const pool = [{ id: 'slime', w: Math.max(2, 10 - this.time * 0.02) }]
        if (this.time > 16) pool.push({ id: 'bat', w: 5 })
        if (this.time > 36) pool.push({ id: 'skeleton', w: 4 })
        if (this.time > 58) pool.push({ id: 'wraith', w: 3.5 })
        if (this.time > 82) pool.push({ id: 'imp', w: 3.5 })
        if (this.time > 106) pool.push({ id: 'hound', w: 4 })
        const type = weightPick(pool).id
        const elite = this.time > 42 && Math.random() < Math.min(0.16, 0.02 + this.time * 0.0006)
        this.spawnRing(type, elite)
      }
      this.spawnTimer = Math.max(0.34, 1.35 - this.time * 0.0055) * rand(0.78, 1.22)
    }
  }

  spawnRing(type, elite = false) {
    const p = this.player
    for (let tries = 0; tries < 14; tries++) {
      const a = rand(0, TAU)
      const d = rand(430, 640)
      const x = clamp(p.x + Math.cos(a) * d, 70, WORLD.w - 70)
      const y = clamp(p.y + Math.sin(a) * d, 70, WORLD.h - 70)
      if (Math.hypot(x - p.x, y - p.y) > 300) {
        this.spawnEnemy(type, x, y, { elite })
        return
      }
    }
    this.spawnEnemy(type, clamp(p.x + 500, 70, WORLD.w - 70), p.y, { elite })
  }

  // ── damage & death ───────────────────────────────────────────────────────
  damageEnemy(e, amount, opts = {}) {
    if (e.dead) return
    const crit = Math.random() < 0.08
    let dmg = amount * (crit ? 1.65 : 1)
    dmg = Math.max(1, Math.round(dmg))
    e.hp -= dmg
    e.flash = 0.09
    const col = opts.color || '#ffe1b3'
    this.addText(e.x + rand(-5, 5), e.y - e.radius - 6, `${dmg}`, crit ? '#ffd86e' : col, crit ? 17 : 13, crit)
    if (!opts.silent) {
      for (let i = 0; i < 2; i++) {
        this.particles.push({
          x: e.x + rand(-e.radius * 0.5, e.radius * 0.5), y: e.y + rand(-e.radius * 0.5, e.radius * 0.5),
          vx: rand(-70, 70), vy: rand(-90, 10), life: rand(0.2, 0.4), maxLife: 0.4,
          size: rand(1, 2.5), color: col, glow: true, shape: 'spark', drag: 0.9,
        })
      }
      sfx('hit')
    }
    if (e.hp <= 0) this.killEnemy(e)
  }

  killEnemy(e) {
    e.dead = true
    this.kills++
    this.score += e.score || 1
    sfx(e.isBoss ? 'bossdown' : 'kill')
    this.burst(e.x, e.y, e.color, e.isBoss ? 50 : 12, e.isBoss ? 5 : 2.6)
    if (e.isBoss) {
      this.shake = 24
      this.effects.push({ type: 'ring', x: e.x, y: e.y, r: 180, r0: 10, life: 1.1, maxLife: 1.1, color: e.color, width: 6, flat: true, layer: 'top' })
      this.burst(e.x, e.y, '#ffe1b3', 30, 4)
      // boss loot
      const gems = 10
      for (let i = 0; i < gems; i++) {
        const a = (i / gems) * TAU + rand(-0.2, 0.2)
        this.pickups.push({ kind: 'big', x: e.x, y: e.y, vx: Math.cos(a) * rand(40, 140), vy: Math.sin(a) * rand(40, 140), v: Math.round(e.xp / gems), life: 60, seed: Math.random(), t: 0 })
      }
      this.pickups.push({ kind: 'heal', x: e.x + 10, y: e.y, vx: 30, vy: -30, life: 60, seed: Math.random(), t: 0 })
      const p = this.player
      p.hp = Math.min(this.maxHp, p.hp + 25)
      this.addText(p.x, p.y - 36, '+25', '#8fffb0', 15)
      if (e.bossKind === 'warden') {
        this.bossKilled.warden = true
        this.bossesSlain++
        this.showBanner('THE WARDEN FALLS')
        this.ui.bossWrap.classList.add('hidden')
        this.bossRef = null
        this.spawnGrace = 3
        this.ui.objective.textContent = 'Prepare for the Hollow King'
      } else if (e.bossKind === 'king') {
        this.bossKilled.king = true
        this.bossesSlain++
        this.ui.bossWrap.classList.add('hidden')
        this.bossRef = null
        this.showBanner('THE HOLLOW KING IS UNMADE')
        this.victoryTimer = 1.6
        this.spawnGrace = 5
        this.enemies.forEach((en) => { if (!en.isBoss) en.dead = true })
      }
      return
    }
    // xp + occasional heal
    this.pickups.push({ kind: e.elite ? 'big' : 'gem', x: e.x, y: e.y, vx: rand(-40, 40), vy: rand(-50, 20), v: e.xp, life: 45, seed: Math.random(), t: 0 })
    if (e.elite) {
      for (let i = 0; i < 2; i++) this.pickups.push({ kind: 'gem', x: e.x, y: e.y, vx: rand(-60, 60), vy: rand(-60, 60), v: 1, life: 45, seed: Math.random(), t: 0 })
    }
    if (Math.random() < 0.055) {
      this.pickups.push({ kind: 'heal', x: e.x, y: e.y, vx: rand(-30, 30), vy: rand(-40, 10), life: 45, seed: Math.random(), t: 0 })
    }
  }

  damagePlayer(amount, source) {
    const p = this.player
    if (this.state !== 'playing' || p.invuln > 0 || p.dashTimer > 0) return
    let dmg = amount
    if (p.shield > 0) {
      const absorbed = Math.min(p.shield, dmg)
      p.shield -= absorbed
      dmg -= absorbed
      this.addText(p.x, p.y - 30, `−${Math.round(absorbed)}`, '#a8c8ff', 12)
      this.effects.push({ type: 'ring', x: p.x, y: p.y - 6, r: 34, r0: 16, life: 0.3, maxLife: 0.3, color: '#a8c8ff', width: 2, layer: 'top' })
      if (p.shield <= 0) { p.shield = 0; sfx('ward') }
    }
    if (dmg > 0) {
      p.hp -= dmg
      this.addText(p.x, p.y - 34, `−${Math.round(dmg)}`, '#ff6b7f', 14)
      this.hurtFlash = 1
      p.hurtTimer = 0.4
      sfx('hurt')
    }
    p.invuln = 0.62
    this.shake = Math.max(this.shake, 8)
    this.burst(p.x, p.y - 8, '#ff5d73', 8, 2.2)
    if (p.hp <= 0) this.die()
  }

  die() {
    if (this.state !== 'playing') return
    const p = this.player
    p.hp = 0
    this.state = 'dead'
    this.saveBest()
    this.burst(p.x, p.y - 10, '#c9a6ff', 50, 4)
    this.burst(p.x, p.y - 10, '#ff9a4d', 30, 3)
    this.shake = 22
    sfx('die')
    this.ui.hud.classList.add('hidden')
    this.ui.levelup.classList.add('hidden')
    this.ui.pauseScreen.classList.add('hidden')
    this.showEnd(false)
  }

  updateVictory(dt) {
    if (this.victoryTimer > 0) {
      this.victoryTimer -= dt
      if (this.victoryTimer <= 0) {
        this.state = 'victory'
        this.saveBest()
        sfx('win')
        this.ui.hud.classList.add('hidden')
        this.showEnd(true)
      }
    }
  }

  showEnd(win) {
    const ui = this.ui
    ui.endScreen.classList.remove('hidden')
    ui.endScreen.classList.toggle('win', win)
    this.endInner.classList.toggle('win', win)
    ui.endTitle.textContent = win ? 'Dawn Breaks over Hollow Grove' : 'The Grove Claims You'
    ui.endSigil.textContent = win ? '☀' : '☾'
    ui.endLine.textContent = win
      ? 'The Hollow King is scattered to cinders. Somewhere beyond the briar, a new morning remembers your name.'
      : 'Your embers gutter out beneath the black boughs. The grove keeps what it takes — but magic leaves a thread to follow.'
    ui.endStats.innerHTML = `
      <div><span>Time</span><b>${this.fmtTime(this.time)}</b></div>
      <div><span>Level</span><b>${this.level}</b></div>
      <div><span>Slain</span><b>${this.kills}</b></div>
      <div><span>Bosses</span><b>${this.bossesSlain}</b></div>`
    ui.endSpells.innerHTML = ''
    for (const id of ['ember', ...SPELL_ORDER.filter((id) => this.spells[id])]) {
      const sp = SPELLS[id]
      const d = document.createElement('div')
      d.className = 'es'
      d.style.setProperty('--c', sp.color)
      d.innerHTML = `${sp.icon}<span>${sp.name}</span><b>${ROMAN[this.spells[id]]}</b>`
      ui.endSpells.appendChild(d)
    }
    const b = this.best
    ui.bestLine.textContent = b.time > 0
      ? `Best · ${this.fmtTime(b.time)} survived · ${b.kills} slain · level ${b.level}`
      : 'Your first descent into the grove'
  }

  // ── XP & level up ────────────────────────────────────────────────────────
  addXp(amount) {
    if (this.state !== 'playing') return
    this.xp += amount * this.xpMult
    while (this.xp >= this.xpNext) {
      this.xp -= this.xpNext
      this.level++
      this.xpNext = this.xpNeeded(this.level)
      this.pendingLevels++
      this.levelBurst()
    }
    if (this.pendingLevels > 0 && this.state === 'playing') this.openLevelUp()
  }

  levelBurst() {
    const p = this.player
    p.hp = Math.min(this.maxHp, p.hp + this.maxHp * 0.12)
    this.effects.push({ type: 'levelup', x: p.x, y: p.y - 8, life: 1.1, maxLife: 1.1, layer: 'top' })
    this.burst(p.x, p.y - 8, '#c9a6ff', 24, 3)
    this.shake = Math.max(this.shake, 4)
    sfx('level')
  }

  openLevelUp() {
    this.state = 'levelup'
    this.cardChoices = this.buildChoices()
    this.ui.newLevel.textContent = this.level
    this.ui.levelup.classList.remove('hidden')
    this.renderCards()
    sfx('level')
  }

  buildChoices() {
    const out = []
    const used = new Set()
    const locked = SPELL_ORDER.filter((id) => !this.spells[id])
    const discovered = Object.keys(this.spells).filter((id) => id !== 'ember')
    const guaranteeNew = locked.length > 0 && (this.level === 2 || (this.level <= 4 && discovered.length < 2) || Math.random() < 0.55)
    if (guaranteeNew) {
      const id = pick(locked)
      out.push(this.spellCard(id, 1, 'new'))
      used.add('s:' + id)
    }

    const candidates = []
    for (const id of Object.keys(this.spells)) {
      if (id === 'ember' && this.spells.ember >= 5) continue
      if (this.spells[id] < SPELLS[id].maxRank) {
        candidates.push({ kind: 'spell', id, w: id === 'ember' ? 2.4 : 2 })
      }
    }
    for (const id of Object.keys(BOONS)) {
      if ((this.boons[id] || 0) < BOONS[id].maxRank) {
        candidates.push({ kind: 'boon', id, w: 1.35 })
      }
    }
    const balls = shuffle(candidates)
    while (out.length < 3 && balls.length) {
      const c = balls.pop()
      const key = (c.kind === 'spell' ? 's:' : 'b:') + c.id
      if (used.has(key)) continue
      used.add(key)
      if (c.kind === 'spell') out.push(this.spellCard(c.id, this.spells[c.id] + 1, 'rank'))
      else out.push(this.boonCard(c.id, (this.boons[c.id] || 0) + 1))
    }
    // extremely late-game filler
    while (out.length < 3) {
      out.push({
        kind: 'filler', id: 'moon', name: "Moon's Favour", tag: 'RESTORATION', color: '#ffe3ae',
        icon: BOONS.vitality.icon, desc: 'Restore all vitality and gain <b>40</b> soul sparks.', rank: 0, maxRank: 0,
      })
    }
    return out
  }

  spellCard(id, rank, kind) {
    const sp = SPELLS[id]
    return {
      kind: kind === 'new' ? 'new' : 'rank', id, rank,
      name: sp.name, tag: kind === 'new' ? 'NEW SPELL' : `RANK ${ROMAN[rank]}`,
      color: sp.color, icon: sp.icon, desc: sp.desc(rank), maxRank: sp.maxRank,
    }
  }

  boonCard(id, rank) {
    const b = BOONS[id]
    return {
      kind: 'boon', id, rank, name: b.name, tag: 'BOON', color: b.color,
      icon: b.icon, desc: b.desc(rank), maxRank: b.maxRank,
    }
  }

  renderCards() {
    const wrap = this.ui.cards
    wrap.innerHTML = ''
    this.cardChoices.forEach((c, i) => {
      const btn = document.createElement('button')
      btn.className = 'card'
      btn.dataset.index = i
      btn.style.setProperty('--card-c', c.color)
      const pips = c.maxRank > 0
        ? `<div class="rank-pips">${Array.from({ length: c.maxRank }, (_, k) => `<i class="${k < c.rank ? 'on' : ''}"></i>`).join('')}</div>`
        : ''
      const tagCls = c.kind === 'new' ? '' : c.kind === 'boon' ? 'boon' : 'upgrade'
      btn.innerHTML = `
        <span class="card-key">${i + 1}</span>
        <span class="card-icon">${c.icon}</span>
        <span class="card-body">
          <span class="card-tag ${tagCls}">${c.tag}</span>
          <span class="card-name">${c.name}</span>
          <span class="card-desc">${c.desc}</span>
          ${pips}
        </span>`
      wrap.appendChild(btn)
    })
  }

  chooseCard(index) {
    if (this.state !== 'levelup') return
    const card = this.cardChoices[index]
    if (!card) return
    const p = this.player
    if (card.kind === 'new') {
      this.spells[card.id] = 1
      this.cds[card.id] = 0.4
      this.buildRail(card.id)
      this.showBanner(`NEW SPELL · ${card.name.toUpperCase()}`)
      this.addText(p.x, p.y - 44, 'NEW SPELL', card.color, 13)
    } else if (card.kind === 'rank') {
      this.spells[card.id] = card.rank
      this.buildRail(card.id)
      this.addText(p.x, p.y - 44, `${card.name} ${ROMAN[card.rank]}`, card.color, 12)
    } else if (card.kind === 'boon') {
      this.boons[card.id] = card.rank
      if (card.id === 'vitality') p.hp = Math.min(this.maxHp, p.hp + 22)
      this.addText(p.x, p.y - 44, card.name, card.color, 12)
    } else {
      p.hp = this.maxHp
      this.addXp(40)
    }
    this.effects.push({ type: 'ring', x: p.x, y: p.y - 6, r: 58, r0: 8, life: 0.55, maxLife: 0.55, color: card.color, width: 3, layer: 'top' })
    this.burst(p.x, p.y - 10, card.color, 18, 2.8)
    this.pendingLevels--
    this.syncHUD(true)
    sfx('card')
    if (this.pendingLevels > 0) {
      this.cardChoices = this.buildChoices()
      this.renderCards()
      sfx('level')
    } else {
      this.ui.levelup.classList.add('hidden')
      this.state = 'playing'
      this.showHint('Spells cast themselves — keep moving', 3.5)
    }
  }

  // ── world objects ────────────────────────────────────────────────────────
  updateZones(dt) {
    for (const z of this.zones) {
      z.life -= dt
      z.tick -= dt
      if (z.tick <= 0) {
        z.tick = z.tickRate
        const dmg = z.type === 'fire' ? z.dmg * 0.8 : z.dmg
        for (const e of this.enemiesIn(z.x, z.y, z.r)) {
          this.damageEnemy(e, dmg, { color: z.type === 'poison' ? '#b8f27a' : z.type === 'fire' ? '#ffab5e' : '#9be6a8', silent: true })
          if (z.slow) e.slow = Math.max(e.slow, 0.7)
        }
        if (Math.random() < 0.3) {
          this.particles.push({
            x: z.x + rand(-z.r * 0.6, z.r * 0.6), y: z.y + rand(-z.r * 0.4, z.r * 0.4),
            vx: rand(-8, 8), vy: rand(-25, -8), life: rand(0.3, 0.7), maxLife: 0.7,
            size: rand(1, 2.2), color: z.type === 'poison' ? '#b8f27a' : z.type === 'fire' ? '#ffab5e' : '#9be6a8',
            glow: true, shape: 'circle', drag: 0.94,
          })
        }
      }
    }
    this.zones = this.zones.filter((z) => z.life > 0)
  }

  updateProjectiles(dt) {
    const p = this.player
    for (const pr of this.projectiles) {
      if (pr.kind === 'vial') {
        pr.t += dt
        const k = Math.min(1, pr.t / pr.dur)
        pr.x = lerp(pr.sx, pr.tx, k)
        pr.y = lerp(pr.sy, pr.ty, k) - Math.sin(k * Math.PI) * 85
        pr.life -= dt
        if (k >= 1) {
          pr.dead = true
          const r = 78 + 8 * pr.rank
          this.zones.push({
            type: 'poison', x: pr.tx, y: pr.ty, r, life: 4, maxLife: 4, tick: 0, tickRate: 0.5,
            dmg: pr.dmg, seed: Math.random(), slow: false,
          })
          this.effects.push({ type: 'ring', x: pr.tx, y: pr.ty, r: r + 6, r0: 6, life: 0.45, maxLife: 0.45, color: '#b8f27a', width: 3, flat: true, layer: 'top' })
          this.burst(pr.tx, pr.ty, '#b8f27a', 16, 3)
          sfx('hit')
        }
        continue
      }
      pr.x += pr.vx * dt
      pr.y += pr.vy * dt
      pr.life -= dt
      if (pr.life <= 0 || pr.x < 0 || pr.y < 0 || pr.x > WORLD.w || pr.y > WORLD.h) { pr.dead = true; continue }

      if (pr.kind === 'enemy') {
        if (Math.hypot(pr.x - p.x, pr.y - p.y) < p.r + pr.r) {
          pr.dead = true
          this.damagePlayer(pr.dmg, pr)
          this.burst(pr.x, pr.y, pr.color, 7, 2)
        }
      } else {
        for (const e of this.enemies) {
          if (e.dead) continue
          if (Math.hypot(pr.x - e.x, pr.y - e.y) < e.radius + pr.r) {
            if (pr.hit && pr.hit.includes(e)) continue
            this.damageEnemy(e, pr.dmg, { color: pr.color })
            this.burst(pr.x, pr.y, pr.color, 3, 1.6)
            if (pr.pierce > 0) {
              pr.pierce--
              if (!pr.hit) pr.hit = []
              pr.hit.push(e)
            } else { pr.dead = true }
            break
          }
        }
      }
    }
    this.projectiles = this.projectiles.filter((pr) => !pr.dead)
  }

  updateStrikes(dt) {
    for (const s of this.strikes) {
      s.delay -= dt
      if (s.delay <= 0) {
        s.done = true
        if (s.type === 'meteor') {
          for (const e of this.enemiesIn(s.x, s.y, s.r)) this.damageEnemy(e, s.dmg, { color: '#ffb266' })
          this.zones.push({
            type: 'fire', x: s.x, y: s.y, r: s.r * 0.85, life: 2.6, maxLife: 2.6, tick: 0, tickRate: 0.5,
            dmg: this.spellDmg(5 + 2 * s.rank), seed: Math.random(), slow: false,
          })
          this.effects.push({ type: 'ring', x: s.x, y: s.y, r: s.r + 20, r0: 10, life: 0.7, maxLife: 0.7, color: '#ff9a4d', width: 5, flat: true, layer: 'top' })
          this.effects.push({ type: 'burst', x: s.x, y: s.y, r: s.r, color: '#ff8a3d', life: 0.6, maxLife: 0.6, layer: 'top' })
          this.burst(s.x, s.y, '#ffb266', 30, 4.5)
          this.shake = Math.max(this.shake, 13)
          sfx('meteor')
        }
      }
    }
    this.strikes = this.strikes.filter((s) => !s.done)
  }

  updatePickups(dt) {
    const p = this.player
    for (const g of this.pickups) {
      g.life -= dt
      g.t += dt
      const dx = p.x - g.x, dy = p.y - 8 - g.y
      const d = Math.hypot(dx, dy)
      if (d < this.magnetRadius) {
        const pull = 260 + (this.magnetRadius - d) * 7
        g.vx += (dx / (d || 1)) * pull * dt
        g.vy += (dy / (d || 1)) * pull * dt
        g.vx *= 0.86
        g.vy *= 0.86
      } else {
        g.vx *= 0.9
        g.vy *= 0.9
      }
      g.x += g.vx * dt
      g.y += g.vy * dt
      if (d < 22) {
        g.dead = true
        if (g.kind === 'heal') {
          const heal = Math.min(this.maxHp - p.hp, 24)
          p.hp += heal
          if (heal > 0) this.addText(p.x, p.y - 34, `+${Math.round(heal)}`, '#8fffb0', 13)
          this.burst(g.x, g.y, '#ff8fa3', 8, 2)
          sfx('heal')
        } else {
          this.addXp(g.v)
          sfx('pickup')
          this.particles.push({ x: g.x, y: g.y, vx: 0, vy: -30, life: 0.3, maxLife: 0.3, size: 3, color: '#b8ffd8', glow: true, shape: 'circle', drag: 0.9 })
        }
      }
    }
    this.pickups = this.pickups.filter((g) => !g.dead && g.life > 0)
  }

  updateCamera(dt) {
    const p = this.player
    const r = this.renderer
    const leadX = clamp(p.aim ? Math.cos(p.aim) * 26 : 0, -30, 30)
    const leadY = clamp(p.aim ? Math.sin(p.aim) * 26 : 0, -30, 30)
    let tx = p.x + leadX, ty = p.y + leadY
    if (r.w < WORLD.w) tx = clamp(tx, r.w / 2, WORLD.w - r.w / 2)
    if (r.h < WORLD.h) ty = clamp(ty, r.h / 2, WORLD.h - r.h / 2)
    const k = 1 - Math.pow(0.0015, dt)
    this.camera.x = lerp(this.camera.x, tx, k)
    this.camera.y = lerp(this.camera.y, ty, k)
  }

  // ── particles / text / effects ───────────────────────────────────────────
  burst(x, y, color, n = 10, spread = 2.2) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU), s = rand(20, 130) * spread * 0.6
      this.particles.push({
        x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s - 30,
        life: rand(0.25, 0.7), maxLife: 0.7, size: rand(1.2, 3.4),
        color, glow: Math.random() > 0.25, shape: Math.random() > 0.7 ? 'spark' : 'circle', drag: 0.9,
      })
    }
    if (this.particles.length > 600) this.particles.splice(0, this.particles.length - 600)
  }

  stepParticles(dt) {
    for (const p of this.particles) {
      p.life -= dt
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.vx *= Math.pow(p.drag || 0.92, dt * 60)
      p.vy *= Math.pow(p.drag || 0.92, dt * 60)
      p.vy += 24 * dt
      if (p.rot !== undefined) p.rot += (p.spin || 0) * dt
    }
    this.particles = this.particles.filter((p) => p.life > 0)
  }

  stepTexts(dt) {
    for (const t of this.texts) {
      t.life -= dt
      t.y -= dt * 30
    }
    this.texts = this.texts.filter((t) => t.life > 0)
  }

  stepEffects(dt) {
    for (const e of this.effects) e.life -= dt
    this.effects = this.effects.filter((e) => e.life > 0)
  }

  addText(x, y, text, color = '#fff', size = 13, crit = false) {
    this.texts.push({ x, y, text, color, size, crit, life: 0.85 })
    if (this.texts.length > 60) this.texts.shift()
  }

  // ── HUD ──────────────────────────────────────────────────────────────────
  syncHUD(force = false) {
    const p = this.player
    const ui = this.ui
    const pct = clamp(p.hp / p.maxHp, 0, 1)
    ui.hpFill.style.width = `${pct * 100}%`
    ui.hpText.textContent = `${Math.ceil(Math.max(0, p.hp))} / ${Math.round(p.maxHp)}`
    ui.xpFill.style.width = `${clamp(this.xp / this.xpNext, 0, 1) * 100}%`
    ui.lvlBadge.textContent = this.level
    ui.killCount.textContent = this.kills
    ui.clock.textContent = this.fmtTime(this.time)
    if (this.bossRef && !this.bossRef.dead) {
      const b = this.bossRef
      ui.bossWrap.classList.remove('hidden')
      ui.bossFill.style.width = `${clamp(b.hp / b.maxHp, 0, 1) * 100}%`
      ui.bossHpText.textContent = `${Math.ceil(b.hp)} / ${Math.round(b.maxHp)}`
      if (ui.bossTitle.textContent !== b.def.name.toUpperCase()) ui.bossTitle.textContent = b.def.name.toUpperCase()
    } else if (!this.bossSpawned.king || this.bossKilled.king) {
      ui.bossWrap.classList.add('hidden')
    }
    // objective
    let obj
    if (this.bossKilled.king) obj = 'Dawn is yours'
    else if (this.bossRef && this.bossRef.bossKind === 'king') obj = 'Defeat the Hollow King'
    else if (this.bossKilled.warden) obj = this.time < 150 ? 'Grow strong for the Hollow King' : 'The Hollow King is coming'
    else if (this.bossRef) obj = 'Slay the Briar Warden'
    else if (this.time < 58) obj = 'Survive the grove · grow your craft'
    else obj = 'Slay the Briar Warden'
    if (ui.objective.textContent !== obj) ui.objective.textContent = obj
    // dash
    const dashPct = p.dashCd > 0 ? (1 - p.dashCd / 1.5) * 100 : 100
    ui.dashCd.style.setProperty('--p', `${dashPct}%`)
    ui.dashBtn.classList.toggle('cooling', p.dashCd > 0)
  }

  updateCooldownUI() {
    if (this.state === 'title') return
    for (const id of Object.keys(this.chipEls)) {
      const chip = this.chipEls[id]
      if (!chip || !chip.cd) continue
      let frac = 0
      if (id === 'ember') {
        const p = this.player
        frac = p.attackCd > 0 ? clamp(p.attackTimer / p.attackCd, 0, 1) : 0
      } else {
        const cdTotal = this.spellCooldown(id, this.spells[id]) / this.castSpeed
        frac = clamp((this.cds[id] || 0) / cdTotal, 0, 1)
      }
      if (frac > 0.01) {
        chip.cd.style.opacity = '1'
        chip.cd.style.transform = `scaleY(${frac})`
      } else if (chip.cd.style.opacity !== '0') {
        chip.cd.style.opacity = '0'
      }
      if (chip.rank !== this.spells[id]) {
        this.buildRail()
        break
      }
    }
    // dash cool visual each frame
    if (this.state === 'playing' || this.state === 'paused') {
      const p = this.player
      const dashPct = p.dashCd > 0 ? (1 - p.dashCd / 1.5) * 100 : 100
      this.ui.dashCd.style.setProperty('--p', `${dashPct}%`)
      this.ui.dashBtn.classList.toggle('cooling', p.dashCd > 0)
    }
  }

  frameUI() {
    // hook for future per-frame HUD; cooldown already updated
  }
}

