input.newString:
let last = performance.now()
let fpsFrames = 0
let fpsAt = last
function frame(now) {
  const dt = Math.min(0.05, Math.max(0.0001, (now - last) / 1000))
  last = now
  game.update(dt)
  renderer.draw(game, input, now / 1000, dt)
  game.frameUI()
  fpsFrames++
  if (now - fpsAt > 1000) {
    game.fps = Math.round((fpsFrames * 1000) / (now - fpsAt))
    fpsFrames = 0
    fpsAt = now
  }
  requestAnimationFrame(frame)
}

